        new Quote { Id = "https://en.wikiquote.org/wiki/Michelangelo_Tamburini", Text = "The reputation for solid virtue, patience, and courage, which he had acquired in the different grades of his order, was by no means dimmed in the long years of his generalate. During Tamburini's superiorship, the apostolic activity of the Society was at its best.", Author = "Michelangelo Tamburini" },
