        new Quote { Id = "https://en.wikiquote.org/wiki/Raquel_Justice", Text = "So far I’ve only played characters who aren’t the nicest and are always the mean girl in some way, but I would really love to switch it up, take on more challenging roles and you know, throw in a splash of kindness here and there", Author = "Raquel Justice" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bernard_Lietaer", Text = "Money is like an iron ring we've put through our noses. We've forgotten that we designed it, and it's now leading us around. I think it's time to figure out where we want to go--in my opinion toward sustainability and community--and then design a money system that gets us there.", Author = "Bernard Lietaer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anike_Agbaje-Williams", Text = "So, I always tell my people that you are either born a broadcaster or train to become one. If you are talented, fine. And if you are not you have to work very hard because the whole world is watching you because being in the broadcast puts you in the limelight.", Author = "Anike Agbaje-Williams" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dineo_Seshee_Bopape", Text = "I think everybody is a post-colonial artist; we’re all living in post-colonial societies.", Author = "Dineo Seshee Bopape" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Girl_vs._Monster", Text = "Scarecrow: Where ya goin'?\nDeimata: It's a Halloween party, I need a costume. [she vanishes]\nScarecrow: You think we need costumes?\nWitch: If you were any stupider, I could sell you as a paperweight.\nScarecrow: Oh, don't be a hater.", Author = "Girl vs. Monster" },
