        new Quote { Id = "https://en.wikiquote.org/wiki/Nicole_LaPointe_Jameson", Text = "I have equity in EG, so I’ll always have some peripheral relationship But trying to make sure everyone’s stable, and that I’m not a blocker to anyone feeling empowered to go into the next stage of EG, is my priority.", Author = "Nicole LaPointe Jameson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wilhelm_Lehmbruck", Text = "Every work of art must retain something from the first days of creation, something of the smell of earth, or one could even say: something animate.", Author = "Wilhelm Lehmbruck" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Larry_Wall", Text = "Although the Perl Slogan is There's More Than One Way to Do It, I hesitate to make 10 ways to do something.", Author = "Larry Wall" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Earle_Sullivan", Text = "We gotta ... rip Trump right out of that office right thereWe ain't about .. waiting until the next election.It's time for revolution.", Author = "John Earle Sullivan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Audrey_Niffenegger", Text = "My family isn’t posh; they’re musicians.", Author = "Audrey Niffenegger" },
