        new Quote { Id = "https://en.wikiquote.org/wiki/Mary_Gilmore", Text = "It’s gettin’ bits o’ posies, ’N’ feelin’ mighty good;A-thrillin’ ’cause she loves you, An’ wond’rin’ why she should;[...]As if there’s nothin’ mattered, As if the world was good,As if the Lord was lookin’, An’ sort o’ understood.", Author = "Mary Gilmore" },
