        new Quote { Id = "https://en.wikiquote.org/wiki/Marnia_Lazreg", Text = "It prompts me to reflect on what defines a human being and how we safeguard the essential humanity within each of us. A democratic nation is constantly at risk of reverting to torture, as it represents a source of unchecked and limitless power.", Author = "Marnia Lazreg" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Angelique_Kerber", Text = "It would be indescribable for any athlete to walk in with the German flag, and it's also a dream of mine", Author = "Angelique Kerber" },
        new Quote { Id = "https://en.wikiquote.org/wiki/French_Rarebit", Text = "Don't they look yummy, yummy?", Author = "French Rarebit" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Summer_Camp_Island_%28season_4%29", Text = "Oscar: Hey, isn't it actually rude to punch someone in the face?\nGhost the Earnest: Huh? Oh, no, you're right! I got wrapped up in judging you that I forgot my manners.\nEmily Ghost: Ahem. Ghost the Earnest, your manners are terrible. You must sign up for retraining and recertification.", Author = "Summer Camp Island (season 4)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alvar_Aalto", Text = "Building art is a synthesis of life in materialised form. We should try to bring in under the same hat not a splintered way of thinking, but all in harmony together.", Author = "Alvar Aalto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nitpicking", Text = "If we find fault with othersWe ourselves are also in the wrong.When other people are in the wrong, we should ignore it,For it is wrong for us to find fault.By getting rid of the habit of fault-findingWe cut off a source of defilement.", Author = "Nitpicking" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Joseph-Edmond_Roy", Text = "D'Argenson made the mistake of wishing to perpetuate in democratic America the exactions of Old World etiquette.", Author = "Joseph-Edmond Roy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Barrington_Levy", Text = "Two months later she said come and get your son", Author = "Barrington Levy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chen_Jining", Text = "We have stayed committed to the Party's decision to establish Comrade Xi Jinping's core position on the Party Central Committee and in the Party as a whole.", Author = "Chen Jining" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_Bird_in_a_Guilty_Cage", Text = "[bruised and battered after getting exploded by the stick of dynamite] Well, birds are off my list! That one sort of upsets my stomach!", Author = "A Bird in a Guilty Cage" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Duran_Duran", Text = "Please, please tell me now.Is there something I should know?Is there something I should sayThat would make you come my way?Do you feel the same?'Cause you don't let it show.", Author = "Duran Duran" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Keturah_Whitehurst", Text = "A child is a child, but a black child is something special, it is special because it is I, it is you; it is personal.", Author = "Keturah Whitehurst" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jeanne_Calment", Text = "I had to wait 110 years to become famous... I intend to enjoy it as long as possible.", Author = "Jeanne Calment" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Valerie_Adams", Text = "The Commission plays a vital role in representing the voices and interests of athletes in our sport, and I am committed to continuing the work done by my predecessor,", Author = "Valerie Adams" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Barbara_Alby", Text = "She was a tireless advocate for the safety of women and children and her legislative legacy is still felt and appreciated by families today.", Author = "Barbara Alby" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Skylanders%3A_SuperChargers", Text = "[hurtly] Grounded? NO! This is so unfair!", Author = "Skylanders: SuperChargers" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sethebe_Manake", Text = "The challenge I found in practise and corporate were the same, there wasn’t enough information for us to make certain decisions in the areas that we were investing in especially those areas we weren’t familiar with.Manake on the challenges in the real estate industry in Africa", Author = "Sethebe Manake" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_H._Madole", Text = "I am proud of being a fascist and a Nazi [...] They [the Jews] have get the same concentration camps as they got in Germany and Italy [...] We've got to get rid of them, the sooner the better.", Author = "James H. Madole" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Toyin_Adewale-Gabriel", Text = "I am a woman of faith and l find the Bible inspirational for living and writing.", Author = "Toyin Adewale-Gabriel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Bradford", Text = "There, but for the grace of God, goes John Bradford.", Author = "John Bradford" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jason_P._Lester", Text = "Running became my way of solving this puzzle of what had happened to me. It was just me and the road.", Author = "Jason P. Lester" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Houleye_Ba", Text = "I always said that sport was my favorite subject until the day a girl introduced me to athletics. She told me there were competitions, that you had to go faster than the others, and that at the end you could get gifts (laughs). After my first race, I never gave up.", Author = "Houleye Ba" },
        new Quote { Id = "https://en.wikiquote.org/wiki/CSI%3A_Miami_%28season_6%29", Text = "Jake: What happened? You get knocked back to uniform?\nFrank: These are stripes, sparky, all right? You're as dumb as you look. I just passed the Sergeant's exam.", Author = "CSI: Miami (season 6)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nonhlanhla_Sitole", Text = "Our goal is to make the entire process seamless, from finding a provider to getting your meds delivered to your home. By making everything tech-based, we are able to simplify, integrate and streamline access to healthcare services. Sitole on the core function of Zoie Health", Author = "Nonhlanhla Sitole" },
        new Quote { Id = "https://en.wikiquote.org/wiki/S%C3%A9bastien_Lefebvre", Text = "It all starts with a good song. You can look cool and work hard, but that won’t be enough. People will get into your coolness once they like the song. That’s when people want to find out more about an artist.", Author = "Sébastien Lefebvre" },
        new Quote { Id = "https://en.wikiquote.org/wiki/East_Timor", Text = "How can we build a country if we don’t invest properly?", Author = "East Timor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pierre-Jean-Mathias_Loras", Text = "During nearly twenty years of devoted work for the church he won the esteem of thousands of its best citizens.", Author = "Pierre-Jean-Mathias Loras" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tolulope_Popoola", Text = "Writers are professional eavesdroppers.", Author = "Tolulope Popoola" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_Serious_Man", Text = "The Uncertainty Principle. It proves we can't ever really know... what's going on. So it shouldn't bother you. Not being able to figure anything out. Although you will be responsible for this on the mid-term.", Author = "A Serious Man" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Outback_%282012_film%29", Text = "[first lines of the film; voice over] Of all the continents on the planet ... There is none quite like... Australia. [The camera zooms into Australia] And it vast, dramatic wilderness called ... The Outback.", Author = "The Outback (2012 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nadia_Buari", Text = "In an era of globalization, only small minds fight against integration. LET BROTHERLY LOVE CONTINUE.", Author = "Nadia Buari" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lorne_Michaels", Text = "When we do well, we do the best comedy on TV. That's not ego; that's just the way it is.", Author = "Lorne Michaels" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lalo_Alcaraz", Text = "It’s what we do as cartoonists, to cut through the [bull] and expose it.", Author = "Lalo Alcaraz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Feli_Nandi", Text = "It was a whole new experience and I got to learn a lot", Author = "Feli Nandi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eleazar", Text = "The appointed duty of Eleazar the son of Aaron the priest is the oil for the light, the sweet incense, the daily grain offering, the anointing oil, the oversight of all the tabernacle, of all that is in it, with the sanctuary and its furnishings.", Author = "Eleazar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Aldo_Cavalli", Text = "The Church is there and will not go away, because its people are there. The mission of priests has become very difficult, but their job is vital, and God is with his Church.", Author = "Aldo Cavalli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Princess_Madeleine%2C_Duchess_of_H%C3%A4lsingland_and_G%C3%A4strikland", Text = "It started as a friendship that grew into something more.", Author = "Princess Madeleine, Duchess of Hälsingland and Gästrikland" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Penn_Warren", Text = "So little time we live in Time, And we learn all so painfully, That we may spare this hour's term To practice for Eternity.", Author = "Robert Penn Warren" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gilles_Deleuze", Text = "A leftist government doesn't exist because being on the left has nothing to do with governments.", Author = "Gilles Deleuze" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bernard_Rollin", Text = "Our treatment of animals is the last moral frontier, the ultimate test of our humanity, the mirror by which we can see most deeply into our own souls.", Author = "Bernard Rollin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Boy_Meets_World_%28season_2%29", Text = "Cory: See, I've been doing my homework.\nAmy: You've done homework?\nCory: It's a metaphor. So how do I avoid years of humiliation and abuse?\nAlan: Don't get married. [Amy smacks him] It's a metaphor!", Author = "Boy Meets World (season 2)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dissidia%3A_Final_Fantasy", Text = "Cid of the Lufaine: Cosmos, the goddess of harmony. Chaos, the god of discord. Reigning from distant realms, the two gods have gathered warriors from all lands to led them in savage war. Cosmos and Chaos were of equal strength it was believed the conflict would last forever. But...", Author = "Dissidia: Final Fantasy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lillian_Nakate", Text = "Oh! I can stand anything. I have learnt to live that way. There is no situation I can’t contain. Politics taught me that. I kept calm in very hard and provoking situations. The beauty with life is that it always moves on despite the challenges.", Author = "Lillian Nakate" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Johann_Gaudenz_von_Salis-Seewis", Text = "Into the silent land!Ah, who shall lead us thither?", Author = "Johann Gaudenz von Salis-Seewis" },
        new Quote { Id = "https://en.wikiquote.org/wiki/J._M._McDermott", Text = "He got in loud fights with Baba all the time. I don’t remember words. Words are never important in arguments, only how loud we shout them.", Author = "J. M. McDermott" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Sanders_Peirce", Text = "True science is distinctively the study of useless things. For the useful things will get studied without the aid of scientific men.", Author = "Charles Sanders Peirce" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maxwell_D._Taylor", Text = "Give me three days and three nights of hard fighting, and you will be relieved.", Author = "Maxwell D. Taylor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gamera_%28film%29", Text = "Alex: Here we are. It looks wild, huh?\nCatherine: You can say that again.", Author = "Gamera (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abbott_and_Costello_Meet_the_Killer%2C_Boris_Karloff", Text = "Ain't I a lucky stiff? Lucky stiff? I should've never left Paterson.", Author = "Abbott and Costello Meet the Killer, Boris Karloff" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ghost_Adventures", Text = "Tagline: Can you handle the lockdown?", Author = "Ghost Adventures" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bhagavad_Gita", Text = "धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः ।मामकाः पाण्डवाश्चैव किमकुर्वत संजय ॥", Author = "Bhagavad Gita" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Witold_Pilecki", Text = "I found a joy in myself, coming from the awareness that I want to fight.", Author = "Witold Pilecki" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sexual_violence_in_South_Africa", Text = "It will dawn on them that over the body of the woman silence is being drawn like a blanket.", Author = "Sexual violence in South Africa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Forest_Whitaker", Text = "[About why he named his daughter True and son Ocean] I want those names to be their destiny, for my daughter to be honest and my son to be expansive. I try to be like a forest, revitalizing and constantly growing. … being called Forest helped me find my identity.", Author = "Forest Whitaker" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Liam_Neeson", Text = "I was reared a Catholic, but I think every day we ask ourselves, not consciously, what are we doing on this planet? What's it all about.", Author = "Liam Neeson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Instant_Star", Text = "Tommy: Look, working on a song... It's like falling in love. First it's a rush, but then it's painful, and sometimes you gotta walk away. But sometimes, you come out with something beautiful, like that song.", Author = "Instant Star" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paranormal_Activity_2", Text = "We just can't let this affect us that much. If we do that, the terrorists win.", Author = "Paranormal Activity 2" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Human_Traffic", Text = "I'm having sex with music, man. And believe me, I can go all night.", Author = "Human Traffic" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Star_Wars%3A_The_Old_Republic", Text = "Jedi = Good to go/T7 = All terrain vehicle.", Author = "Star Wars: The Old Republic" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Israel_Matseke_Zulu", Text = "I grew up in court. I knew the justice system. Boys will be boys was the judgement and I knew the judgement before it was even given.", Author = "Israel Matseke Zulu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rise_of_the_Teenage_Mutant_Ninja_Turtles", Text = "Turtles and Splinter: Hot soup!", Author = "Rise of the Teenage Mutant Ninja Turtles" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gary_Zukav", Text = "Hindu mythology is virtually a large scale projection into the psychological realm of microscopic scientific discoveries. … The Wu Li Masters know that physicists are doing more than discovering the endless diversity of nature. They are dancing with Kali, the Divine Mother of Hindu mythology.", Author = "Gary Zukav" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kenny_the_Shark", Text = "Kenny: Oh Kat, you've come to say goodbye!\nKat: Cut the drama, Kenny.", Author = "Kenny the Shark" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mmakgosi_Anita_Tau", Text = "We are not second class citizens. We will no longer live life in an eternal state of apology for being women.", Author = "Mmakgosi Anita Tau" },
        new Quote { Id = "https://en.wikiquote.org/wiki/B._B._Lal", Text = "I don't say so, but my spade tells me so.", Author = "B. B. Lal" },
        new Quote { Id = "https://en.wikiquote.org/wiki/To_Wong_Foo%2C_Thanks_for_Everything%21_Julie_Newmar", Text = "The seats are like butter!", Author = "To Wong Foo, Thanks for Everything! Julie Newmar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Sullivan_Dwight", Text = "Work, and thou wilt bless the dayEre the toil be done;They that work not, can not pray,Can not feel the sun.God is living, working still,All things work and move;Work, or lose the power to will,Lose the power to love.", Author = "John Sullivan Dwight" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ravens", Text = "Raven, raven, your eggs are shining bright!Raven bird, your eggs are shining bright!Where do people carry off your holy eggs?", Author = "Ravens" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Star_Wars_Episode_III%3A_Revenge_of_the_Sith_%28video_game%29", Text = "Anakin: The General's command ship is dead ahead.", Author = "Star Wars Episode III: Revenge of the Sith (video game)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Monica_Azuba_Ntege", Text = "It is owned 100 percent by the Ugandan government, but after that the plan is to work with other airlines and in future we will float share.", Author = "Monica Azuba Ntege" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wen_Jiabao", Text = "China has established friendship with many African countries, and is opening itself up to Africa and providing assistance. It is cooperating with African countries on an equal basis and has no desire to colonize Africa.", Author = "Wen Jiabao" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Global_warming", Text = "I'm agnostic as to the causes. All I know is there is water where there once was ice.", Author = "Global warming" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Longest_Journey", Text = "There's a storm heading this way. Even the weather sucks in my dreams. I feel so charmed.", Author = "The Longest Journey" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Miriam_Peretz", Text = "I am so glad that you asked! People so often focus on the last few years, and forget that I, like every other person, have roots. My roots are in Morocco, even though my dreams have always been in Eretz Yisrael", Author = "Miriam Peretz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pirates_of_the_Caribbean%3A_The_Curse_of_the_Black_Pearl", Text = "A wedding? I love weddings! Drinks all around!", Author = "Pirates of the Caribbean: The Curse of the Black Pearl" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Glenda_Glover", Text = "Pearls represent refinement and wisdom. We train young ladies to be leaders and to make sure they have the wisdom to lead…and that goes hand in hand with the true meaning of what Alpha Kappa Alpha is all about. The strand of pearls speaks to solidarity among the members.", Author = "Glenda Glover" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Warlock", Text = "Music is the outward and audible signification of inward and spiritual realities.", Author = "Peter Warlock" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Picture_Perfect_%281997_film%29", Text = "Sam Mayfair: ...it's like, even though you're engaged, when you're with me I really feel like you're WITH me, you know? But the scary thing is I actually kinda like it.", Author = "Picture Perfect (1997 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Joan_Mir%C3%B3", Text = "The plate that a peasant eats his soup out of is much more interesting to me than the ridiculously rich plates of rich people.", Author = "Joan Miró" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Morrissey", Text = "It's so easy to laugh, it's so easy to hate, it takes strength to be gentle and kind.", Author = "Morrissey" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Miss_Fisher%27s_Murder_Mysteries", Text = "[Phryne reads an invitation.]\nPhryne Fisher: A luncheon. Today. With Lydia Andrews. How lovely! …oh. And Aunt Prudence.\nDr. Elizabeth Mac McMillan: Shame I have to perform an urgent bowel operation.", Author = "Miss Fisher's Murder Mysteries" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nana_Aba_Anamoah", Text = "Giant slayers don’t waste weapons on ants...when God places his oil on you, you choose your battles. Choose your battles. It is not every battle you fight.", Author = "Nana Aba Anamoah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Li_Shangfu", Text = "In China, we have a city called Shangri-La in Yunnan Province and a small town also called Shangri-La in Sichuan Province. Shangri-La is synonymous with a utopia of purity, beauty, harmony and serenity.", Author = "Li Shangfu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Licorice_Pizza", Text = "Fuck off, teenagers!", Author = "Licorice Pizza" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Venus_%28mythology%29", Text = "Quotes are arranged alphabetically by author", Author = "Venus (mythology)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Don_Giovanni", Text = "Notte e giorno faticar,Per chi nulla sa gradir,Piova e vento sopportar,Mangiar male e mal dormir.Voglio far il gentiluomoE non voglio più servir.", Author = "Don Giovanni" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Father_of_the_Bride_Part_II", Text = "We could sell this house is a second. It's the Leave It To Beaver house that everybody wants.", Author = "Father of the Bride Part II" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Quentin_Crisp", Text = "A pinch of notoriety will do.", Author = "Quentin Crisp" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Toyin_Raji", Text = "Be something, have something, feel something.", Author = "Toyin Raji" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rebirth_of_Mothra", Text = "She's Mothra. She's Back. And She's Mad!", Author = "Rebirth of Mothra" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ham_on_Rye_%28film%29", Text = "Hailey: Are we gonna be late?Girl #1: Yeah. That's the idea. We don't wanna rush a day we're gonna remember for the rest of our lives.[...]Girl #2: Hello? We want to be late!Hailey: Right...", Author = "Ham on Rye (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tom_Burns_%28bishop%29", Text = "I feel unworthy to have been chosen by the Lord to be a Priest and then a Bishop, to navigate waters that have become increasingly challenging, yet day by day were filled with so many graces. I thank the Lord, as well as clergy and people, for so many blessings, and ask forgiveness for my failings.", Author = "Tom Burns (bishop)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Noemi_Di_Segni", Text = "Today is a day for Italy, not a pat on the back for Jews. Antisemitism is not a problem for Jews — it's a problem for society.", Author = "Noemi Di Segni" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Resego_Kgosidintsi", Text = "The fight against Gender-Based Violence cannot be won by an individual or a movement that works in isolation and we all need to join hands in fighting for the rights of women and children.", Author = "Resego Kgosidintsi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Black_Books", Text = "Manny: I am a loose lily drifting down an amber river", Author = "Black Books" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fulke_Greville%2C_1st_Baron_Brooke", Text = "Hard-hearted minds relent and rigor's tears abound, And envy strangely rues his end, in whom no fault was found. Knowledge her light hath lost, valor hath slain her knight, Sidney is dead, dead is my friend, dead is the world's delight.", Author = "Fulke Greville, 1st Baron Brooke" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sylvia_Bozeman", Text = "I didn't know they lay of the land, quips Bozeman. They wanted her to go back to school to finish her Ph.D. She just looked at them thinking, I have a husband and two small children, how am I going to go back to Vanderbilt four hours away?", Author = "Sylvia Bozeman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pancho_Villa", Text = "Men will not forget that Pancho Villa was loyal to the cause of the people.", Author = "Pancho Villa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lindani_Nkosi", Text = "I want to tell stories about humans and our dilemmas. I want to explore things that impact our soul, mind and society. Something that is deeper and teaches people about themselves.", Author = "Lindani Nkosi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Right_to_keep_and_bear_arms", Text = "In a constitutional government the fighting-men have the supreme power, and those who possess arms are the citizens.", Author = "Right to keep and bear arms" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Augustus_De_Morgan", Text = "All existing things upon this earth, which have knowledge of their own existence, possess, some in one degree and some in another, the power of thought, accompanied by perception, which is the awakening of thought by the effects of external objects upon the senses.", Author = "Augustus De Morgan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Henry_M._Morris", Text = "The only way we can determine the true age of the earth is for God to tell us what it is. And since he has told us, very plainly, in the Holy Scriptures that it is several thousand years of age, and no more, that ought to settle all basic questions of terrestrial chronology.", Author = "Henry M. Morris" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Catherine_Muraga", Text = "I am excited to be joining the ADC at this particular time and look forward to continuing the tremendous work that has already begun.", Author = "Catherine Muraga" },
        new Quote { Id = "https://en.wikiquote.org/wiki/L.A._Noire", Text = "Friends who want to stay friends don't discuss religion or politics. In my case you can add the war to that.", Author = "L.A. Noire" },
        new Quote { Id = "https://en.wikiquote.org/wiki/English_nationalism", Text = "Poitiers and Cressy tell,When most their pride did swell,Under our swords they fell: No less our skill isThan when our grandsire great,Claiming the regal seat,By many a warlike feat Lopp’d the French lilies.’", Author = "English nationalism" },
        new Quote { Id = "https://en.wikiquote.org/wiki/April_20", Text = "3 Zarbon 06:12, 18 April 2008 (UTC)", Author = "April 20" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Incredibles", Text = "[repeated phrase] Showtime!", Author = "The Incredibles" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Damsel", Text = "There are many stories of chivalry where the heroic knight saves the damsel in distress. This is not one of them.", Author = "Damsel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Howard_M._Wiseman", Text = "No paper is more seminal for the fields of quantum foundations and quantum information than the 1935 Einstein, Podolsky and Rosen (EPR) paper.", Author = "Howard M. Wiseman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brumhilda_Ochs", Text = "I plan to be the best me. I believe that there’s nothing more unique and beautiful then being yourself 100% and representing one’s country to the best of you ability", Author = "Brumhilda Ochs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Parihaspore", Text = "[T]he glorious silver [image of Visnu] Parihasakesava [which] shone like the god [Visnu] ... the famous [image of] Visnu Muktakesava, made of gold; the [image of Visnu] Mahavaraha.", Author = "Parihaspore" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Clarisse_Imaniriho", Text = "Another thing is to listen to the voice of the youth, understand their problems and partner with institutions that we can work with in identifying and addressing youth challenges at the right time.", Author = "Clarisse Imaniriho" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Salma_Agha", Text = "The emotions conveyed through your performance will be etched in our memories for years to come.", Author = "Salma Agha" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_McKeen", Text = "Fear and Loathing in Las Vegas is perfect in the same way that The Great Gatsby is perfect. Take a pencil and read these books, looking for something that doesn't sound right, something you'd want to change. You'll leave the page untouched.", Author = "William McKeen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Cahill", Text = "Well, I’ll give you that Congresswoman Waters may have given you something on appeal that may result in this whole trial being overturned", Author = "Peter Cahill" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Discourse_on_the_Method", Text = "Of all things, good sense is the most fairly distributed: everyone thinks he is so well supplied with it that even those who are the hardest to satisfy in every other respect never desire more of it than they already have. (fr; en)", Author = "Discourse on the Method" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Caucher_Birkar", Text = "In Tehran university, at the math club, where I was studying the pictures of Fields medalists were lining the walls. I looked at them and said to myself, ‘Will I ever meet one of these people?’ At that time in Iran, I couldn’t even know that I’d be able to go to the West.", Author = "Caucher Birkar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/List_of_people_by_name%2C_C", Text = "Calvert, Cecil, 2nd Baron Baltimore", Author = "List of people by name, C" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Sandlot", Text = "[voiceover] Only one kid in history had ever attempted what Benny was about to...and he got eaten. So we were worried, real worried, even when Benny brought out the secret weapon: Shoes guaranteed to make a kid run faster and jump higher—P.F. Flyers.", Author = "The Sandlot" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Assault_weapon", Text = "The only use for assault weapons is to shoot people.", Author = "Assault weapon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Integrity", Text = "A musician would not willingly consent that his lyre should be out of tune, nor a leader of a chorus that his chorus should not sing in the strictest possible harmony; but shall each individual person be at variance with himself, and shall he exhibit a life not at all in agreement with his words?", Author = "Integrity" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fire_Birds", Text = "Mr. Preston, this operation will be a failure if we all die!", Author = "Fire Birds" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sting_%28musician%29", Text = "Dissent is a legitimate and essential right in any democracy and modern politicians must accept this fact with tolerance. A sense of proportion — and a sense of humour — is a sign of strength, not a sign of weakness.", Author = "Sting (musician)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jacoba_van_Heemskerck", Text = "Nothing special is happening here in the paintersworld [of the Netherlands]; everything stays firmly the same. (translation, Fons Heijnsbroek, 2018)", Author = "Jacoba van Heemskerck" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Aucassin_and_Nicolette", Text = "Qui vauroit bons vers oïrDel deport du viel antif,De deus biax enfans petis,Nicholete et Aucassins,Des grans paines q'il soufri,et de proueces q'il fist,Por s'amie o le cler vis?", Author = "Aucassin and Nicolette" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christian_Wolmar", Text = "People expect to be able to use wi-fi on a train in the same way they would use a toilet.", Author = "Christian Wolmar" },
