        new Quote { Id = "https://en.wikiquote.org/wiki/8_Seconds", Text = "[about marriage] I guess it's like bull riding. You gotta stay on and try not to get bucked off.", Author = "8 Seconds" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Becky_Lynch", Text = "But the only thing that's ending on Saturday night is your five-hundred-day title reign when I become the Raw Women's Champion.", Author = "Becky Lynch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Uttu", Text = "All the yarns of Uttu, the splendour of kingship, belong to me.", Author = "Uttu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thiruvalluvar", Text = "There is no greater wealth than Virtue,And no greater loss than to forget it.", Author = "Thiruvalluvar" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peace_on_Earth_%28film%29", Text = "Thou shalt not kill. Sounds like a mighty good book of rules, but them men didn’t follow them.", Author = "Peace on Earth (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rozario_Menezes", Text = "When we have God at the centre of our Church, we can lead our people to reach God's Kingdom. Without God at the centre or our Church surrounding God, then not much of anything can be achieved.", Author = "Rozario Menezes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Khamba_Thoibi", Text = "H. Anganghal Singh's Khamba Thoibi Sheireng (Poem on Khamba Thoibi, 1940) is a national epic of the Manipuris based on the story of Khamba and Thoibi of Moirang. The poet composes the whole epic in the Pena Saisak style of folk ballads sung by minstrels or bards popular in Manipur.", Author = "Khamba Thoibi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bukky_Wright", Text = "If there is love and understanding, the sky will be one’s beginning. The first thing you would want to beg God for is for Him to give you an understanding partner.", Author = "Bukky Wright" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bosede_Afolabi", Text = "My interest in Obstetrics and Gynaecology developed from a combination of how well I was trained in the subject in medical school, as well as my affinity and empathy for female patients. I remember that I felt a lot of sympathy for pregnant women, especially those who couldn’t afford care.", Author = "Bosede Afolabi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Galefele_Moroko", Text = "I have started light training with the advice of my coach. I feel no pain in the angle now but I will take it slowly as per the program.", Author = "Galefele Moroko" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cheikh_Hamidou_Kane", Text = "....the work of the spirit and the work of the field.", Author = "Cheikh Hamidou Kane" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paranoia", Text = "Paranoia is infectious. It’s also an incredibly useful tool. If you can make people afraid enough, uncertain enough, they will simply stop moving.", Author = "Paranoia" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yuga_cycle", Text = "A hundred to you, ten thousand years, two Yugas, three Yugas, four we make.", Author = "Yuga cycle" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Draupadi", Text = "Sanskrit transliteration IAST: ahalyā draupadī sītā tārā mandodarī tathā ।pañcakanyāḥ smarennityaṃ mahāpātakanāśinī॥", Author = "Draupadi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mikhail_Kalinin", Text = "You must remember that we persecute nobody for religion. We regard religion as an error and fight it with education.", Author = "Mikhail Kalinin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Benjamin_Mkapa", Text = "Our reason for withdrawal is simple. We are party to too many regional trading organisations. The sum effect of this means that our membership is extremely costly to sustain and we must rationalise our participation in such ventures.", Author = "Benjamin Mkapa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Urwibutso_Nicole", Text = "This program ensures that young players, especially girls, receive physical fitness training and the necessary support to overcome challenges faced in past competitions .", Author = "Urwibutso Nicole" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bamboozled", Text = "As I bled to death, as my very life oozed out of me, all I could think of was something the great Negro James Baldwin had written. People pay for what they do, and still more for what they have allowed themselves to become, and they pay for it, very simply, by the lives they lead.", Author = "Bamboozled" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mickey_Spillane", Text = "Those big-shot writers … could never dig the fact that there are more salted peanuts consumed than caviar.", Author = "Mickey Spillane" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oded_Fehr", Text = "The things I learned from the army - and I think it was a lesson for life - was how to work in unison with other people. How to take responsibility. Things like that I learned in the army.", Author = "Oded Fehr" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cristina_Lizardo", Text = "I wish to say that the right to life is not a religious question, but rather a moral and juridical one, and that is a commandment from God.", Author = "Cristina Lizardo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Shelton_Mackenzie", Text = "Too famous, for his life was pure, And man can ill another's fame endure.", Author = "Robert Shelton Mackenzie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ruger", Text = "Comparison is a killer of joy, but it's necessary for the game. This is what is entertaining these people.", Author = "Ruger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rebecca_Miano", Text = "Success is going beyond some expectations with excellence, not perfection but with excellence. Because excellence is where you do consistently something well. I have made a difference with excellence. And I think I have broken the boundaries.", Author = "Rebecca Miano" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ennio_Antonelli", Text = "The family is the most efficient school of humanity of Christian life, transmitting human and Christian values in its own peculiar manner, based on example and testimony, on experience and daily life.", Author = "Ennio Antonelli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Giovanni_Schiaparelli", Text = "Mercury on its axis turns like the Moon:One side has lasting day, the other night;One side in everlasting fire doth swoon;While th'other hides forever from the light.", Author = "Giovanni Schiaparelli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Joxe_Azurmendi", Text = "The price of freedom is to decide moral and political issues.", Author = "Joxe Azurmendi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hipparchus", Text = "I have composed a book on the length of the year in which I show that the tropical year contains 365 days plus a fraction of a day which is not exactly 1/4 days as the mathematicians-astronomers suppose, but which is less than 1/4 by about 1/300.", Author = "Hipparchus" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Onyinye_Ough", Text = "I strongly believe we have hope of properly tackling corruption in Nigeria.", Author = "Onyinye Ough" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Waldo_Tobler", Text = "The conceptualization of a map as a data-storage medium leads directly to the concept of it as a computer input element.", Author = "Waldo Tobler" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bad_Taste", Text = "Stick all the bits of brain in a plastic bag, Barry.", Author = "Bad Taste" },
        new Quote { Id = "https://en.wikiquote.org/wiki/September_8", Text = "0 Kalki 20:49, 7 September 2009 (UTC) * 2 Kalki 16:28, 7 September 2005 (UTC) I would rank this higher, with a 3, or even a 4, but it is not sourced, and I have not yet found much to go on definitely tying it or anything like it to Sellers.", Author = "September 8" },
