        new Quote { Id = "https://en.wikiquote.org/wiki/Game_of_Thrones/Season_5", Text = "Daenerys Targaryen: Angry snakes lash out, makes chopping off their heads a lot easier. Find the men who did this, and bring them to me.", Author = "Game of Thrones/Season 5" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michel_Fugain", Text = "Time always keeps short in the happy guns and I will not have time I will not have time", Author = "Michel Fugain" },
