        new Quote { Id = "https://en.wikiquote.org/wiki/Rob_Riemen", Text = "Whitman’s masterpiece, his whole vision, is exactly about this: life as a quest for truth, love, beauty, goodness, and freedom; life as the art of becoming human through the cultivation of the human soul.", Author = "Rob Riemen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fingers", Text = "FOREFINGER, n. The finger commonly used in pointing out two malefactors.", Author = "Fingers" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fun_and_Fancy_Free", Text = "You know, you worry too much. In fact, everybody worries too much.", Author = "Fun and Fancy Free" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Twilight_Zone_%282002_TV_series%29", Text = "Forest Whitaker: Meet the Winslows, a family searching for a way to control their troubled teen. How far they're willing to go will take them to a gated community whose address can only be found in the Twilight Zone.", Author = "The Twilight Zone (2002 TV series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Victoria_%26_Abdul", Text = "I suddenly feel a great deal better.", Author = "Victoria & Abdul" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lev_Landau", Text = "Главное, делайте всё с увлечением, это страшно украшает жизнь.", Author = "Lev Landau" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Lai", Text = "When coal-fired power generation is a necessity for Taiwan, the Linkou Power Plant, equipped with the most advanced generators and pollution control and abatement systems and burning the types of coal that have the fewest impurities, is the model we look toward.", Author = "William Lai" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Julian_Haviland", Text = "[On the Battle of Orgreave] When the horses rode through some of the miners and knocked a few down, the Queen said words [to the effect of], Oh, that’s awful! Oh, we shouldn’t do that!.And for the Queen to make a political comment like that was news.", Author = "Julian Haviland" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Planet_Hulk_%28film%29", Text = "Finally! Now I know who to smash!", Author = "Planet Hulk (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Rosen_%28rabbi%29", Text = "The current treatment of animals in the livestock trade definitely renders the consumption of meat as halachically unacceptable as the product of illegitimate means.", Author = "David Rosen (rabbi)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Devil_and_Daniel_Mouse", Text = "[At the beginning of the documentary, How We Made The Devil and Daniel Mouse; off-screen] Hold everything! STOP! This isn't The Devil and Daniel Mouse! This is the film, uh, about How We Made The Devil and Daniel Mouse. Actually, it was easy.", Author = "The Devil and Daniel Mouse" },
