        new Quote { Id = "https://en.wikiquote.org/wiki/Edmond_Halley", Text = "Wherefore, if, according to what we have already said, it should return again about the year 1758, candid posterity will not refuse to acknowledge that this was first discovered by an Englishman.", Author = "Edmond Halley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hollywood_7", Text = "Jo: Which one’s the best looking?\nHannah: Well, Nick looks like Matt Damon and Matt looks like Nicholas Cage.\nPaul: Well, that’s easy: who do you like more, Matt Damon or Nick Cage?\nHannah: Actually, I’ve always preferred Sean Connery.\nPaul: Problem solved. You’ve won a date with my granddad, then.", Author = "Hollywood 7" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mariska_Hargitay", Text = "When I walk down the street and people say, 'I knew what to do because of watching your show (Law & Order: Special Victims Unit). I knew not to shower. I reported immediately. I took myself to the hospital instead of saying forget it, forget this ever happened, That's what I'm most proud of.", Author = "Mariska Hargitay" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ruth_Harrison", Text = "In fact if one person is unkind to an animal it is considered to be cruelty, but where a lot of people are unkind to a lot of animals, especially in the name of commerce, the cruelty is condoned and, once large sums of money are at stake, will be defended to the last by otherwise intelligent people.", Author = "Ruth Harrison" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Care_Bears_%28TV_series%29", Text = "Lotsa Heart Elephant: And That's the truth!", Author = "Care Bears (TV series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Santa_Claus", Text = "Bernard Shaw (I strongly suspect) began to disbelieve in Santa Claus at a discreditably early age.", Author = "Santa Claus" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Etheldreda_Nakimuli-Mpungu", Text = "They say their patients don’t have those issues and don’t want you to screen them because they don't want it to be known that the patients they care for may have an alcohol problem or depression,", Author = "Etheldreda Nakimuli-Mpungu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vivian_Onano", Text = "Achieving gender equality is more than 50-50 representation; it is also about recognizing and respecting women’s rights as human rights, treating women with dignity, offering them equal opportunities to participate fully in the socioeconomic and political development of their individual countries", Author = "Vivian Onano" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Colm_T%C3%B3ib%C3%ADn", Text = "A novelist could probably run a military campaign with some success. They could certainly run a country.", Author = "Colm Tóibín" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anne_Stevenson", Text = "Blackbirds are the cellos of the deep farms.", Author = "Anne Stevenson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lynne_Muthoni_Wanyeki", Text = "What I want for myself and for all African women, is autonomy, choice and freedom, health, and happiness.", Author = "Lynne Muthoni Wanyeki" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_Little_Princess_%281973_TV_serial%29", Text = "Didn't your father ever tell you that you were a princess?", Author = "A Little Princess (1973 TV serial)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Catherine_Webb", Text = "Complexity should be your excuse for inaction.", Author = "Catherine Webb" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Return_to_Lonesome_Dove", Text = "Captain Woodrow F. Call: Leave it to Augustus... first man I know who could get himself into a shootin' scrape after he was dead.", Author = "Return to Lonesome Dove" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Skyfall", Text = "[re. the porcelain bulldog on M's desk.] The whole office goes up in smoke and that bloody thing survives?", Author = "Skyfall" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Katie_Britt", Text = "I believe God commands us to support Israel.", Author = "Katie Britt" },
