        new Quote { Id = "https://en.wikiquote.org/wiki/The_Thing_Around_Your_Neck", Text = "She could not complain about not having shoes when the person she was talking to had no legs", Author = "The Thing Around Your Neck" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nicholas_Briggs", Text = "If we were to be strictly ‘logical’ about how the voice should sound, it would be utterly monotonous and boring to listen to. All the things that grab our attention in a human voice are to do with emotions.", Author = "Nicholas Briggs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Andreas_Mogensen", Text = "Even though we (astronaut candidates) are doing science, we are in many ways the hands and the eyes of the experts who are on the ground, and so we are kind of an extension of them.", Author = "Andreas Mogensen" },
