        new Quote { Id = "https://en.wikiquote.org/wiki/May_3", Text = "3 ♞☤☮♌︎Kalki ⚚⚓︎⊙☳☶⚡ 11:07, 28 February 2013 (UTC) with a slight lean toward 4.", Author = "May 3" },
