        new Quote { Id = "https://en.wikiquote.org/wiki/Alfred_Xuereb", Text = "The Holy See wishes to offer its support to any initiative in favour of dialogue and reconciliation and also take advantage of this to bring the Good News of Jesus Christ to North Korea.", Author = "Alfred Xuereb" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Haley_Lu_Richardson", Text = "This is really embarrassing to say, but it’s sincere, One of the reasons [I became an actor] was because maybe I could get famous enough to meet the Jonas Brothers one day.", Author = "Haley Lu Richardson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Afnan_Ullah_Khan", Text = "At least now the world know, why he did, what he did #Gaza_Genicide", Author = "Afnan Ullah Khan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stella_Mwangi", Text = "To say something is impossible is to fear. I have no space for the word impossible. I don't tolerate it. Sometimes it gets me in trouble, but whatever it is, I will face it.", Author = "Stella Mwangi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Matilda_Lambert", Text = "I had always wanted to be an ambassador and a pilot. When I finally started flying, I didn’t want to be anything close to being a pilot.", Author = "Matilda Lambert" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Scott_Moir", Text = "I don’t think revenge is enough to fuel the fire it takes to go to an Olympic Games and be successful.", Author = "Scott Moir" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Prithu", Text = "He levelled the whole earth, clearing it of ups and downs, and encouraged cultivation, cattle-breeding, commerce and building of cities and villages.", Author = "Prithu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Randy_Shilts", Text = "I can only answer that I tried to tell the truth and, if not be objective, at least be fair; history is not served when reporters prize trepidation and propriety over the robust journalistic duty to tell the whole story.", Author = "Randy Shilts" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Albert_Gleizes", Text = "People crowded into our room, they shouted, they laughed, they got worked up, they protested, they luxuriated in all kinds of utterances.", Author = "Albert Gleizes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cool_World", Text = "You've had enough of me? You've had enough of me, you piece of shit? You screwed us all for a piece of ass? And you've had enough of me? Where is she? It's the oldest law in Cool World. I've never had to enforce it. You cross that line, I'll slap you around and make you piss like a puppy.", Author = "Cool World" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lightyear_%28film%29", Text = "I'm Buzz Lightyear, I'm always sure!", Author = "Lightyear (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bernard_Jenkin", Text = "Strategy is a constant reconciling of possibilities, means and ends.", Author = "Bernard Jenkin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dragon_Ball_Z%3A_Wrath_of_the_Dragon", Text = "Tapion: Now here I am, a thousand years later and nothing's changed. Still a prisoner outside, looking in.", Author = "Dragon Ball Z: Wrath of the Dragon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A_Christmas_Carol_%281938_film%29", Text = "You owe me a shilling!", Author = "A Christmas Carol (1938 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Henry_Wotton", Text = "How happy is he born and taught,That serveth not another's will;Whose armor is his honest thought,And simple truth his utmost skill!", Author = "Henry Wotton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lafcadio_Hearn", Text = "How sweet Japanese woman is! All the possibilities of the race for goodness seem to be concentrated in her.", Author = "Lafcadio Hearn" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Annie_%281999_film%29", Text = "[sings before she is banished] I'm headed straight for the nut house! With all the nuts and the squirrels! And there I'll stay, tucked away, till the prohibition of... little... GIRLS!", Author = "Annie (1999 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Burney", Text = "He certainly over-heated himself at Venice by walking at a season when it is said that only Dogs and Englishmen are seen out of doors at noon, all else lie down in the middle of the day.", Author = "Charles Burney" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mamallapuram", Text = "Where frowns that sacred city hewn from stone,The plover cries, the jackall makes his moan.", Author = "Mamallapuram" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Total_Drama_World_Tour", Text = "Chris: Owen, DJ, and Harold? Guys?", Author = "Total Drama World Tour" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Henry_Fountain_Ashurst", Text = "A speech is entertaining only when serenely detached from all information.", Author = "Henry Fountain Ashurst" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ellen_Sturgis_Hooper", Text = "I slept, and dreamed that life was Beauty;I woke, and found that life was Duty.Was thy dream then a shadowy lie?Toil on, poor heart, unceasingly;And thou shalt find thy dream to beA truth and noonday light to thee.", Author = "Ellen Sturgis Hooper" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Baptiste-Louis_Crevier", Text = "[[Seiano | [sic]]] is known throughout the world as the most renowned example of the prodigious rise and frightful fall of a favorite, who [sic] of fortune of him. (volume III, book VI, p. 7)", Author = "Jean-Baptiste-Louis Crevier" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Shaffer", Text = "The men climb the Andes.", Author = "Peter Shaffer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Everybody%27s_Golf_4", Text = "It's not my fault! Some kid's controlling me!", Author = "Everybody's Golf 4" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lady_Anne_Granard_%28or_Keeping_up_Appearances%29", Text = "No one dies but some one is glad of it.", Author = "Lady Anne Granard (or Keeping up Appearances)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Swathi_Thirunal_Rama_Varma", Text = "My sense of the high advantage derived from this establishment in a scientific point of view, as I am fully sensible that by reason of my patronizing it, my name, however, undeserving of any celebrity is favorably noticed even in distant regions, among the scientific personages of the present day.", Author = "Swathi Thirunal Rama Varma" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rosemary_Tonks", Text = "Thinking we were safe-insanity!We went in to make love. All the sameIdiots to trust the little hotel bedroom.Then in the gloom......And who does not know that pair of shuttersWith all the awkward hook on themAll screeching whispers?", Author = "Rosemary Tonks" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Daniel_Handler", Text = "For Beatrice--Darling, dearest, dead.", Author = "Daniel Handler" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Proletarian_nation", Text = "Strasser and his associates had responded to the socialist appeal of the times, but ‘not as to the call of the proletarian class but of proletarian nations.’", Author = "Proletarian nation" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Naughty_Nineties", Text = "Dexter Broadhurst: Now it don't look nice chewing gum in that suit!\nSebastian Dinwiddle: I'm chewin' it in my mouth.", Author = "The Naughty Nineties" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Whose_Life_Is_It_Anyway%3F_%281981_film%29", Text = "Some nurses and I went out for a little midnight skateboarding last night. The only trouble was that I was the skateboard.", Author = "Whose Life Is It Anyway? (1981 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lewis_Grizzard", Text = "I know lots of people who are educated far beyond their intelligence.", Author = "Lewis Grizzard" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Country_of_My_Skull", Text = "And everyone wants to know: Who? Why? The victims ask the hardest of all the questions: How is it possible that the person I loved so much lit no spark of humanity in you?", Author = "Country of My Skull" },
        new Quote { Id = "https://en.wikiquote.org/wiki/MobLand", Text = "I get six weeks in solitary and", Author = "MobLand" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nnenna_Oti", Text = "The pastor and the mother in me will not permit me to do anything that will adversely affect the future of our children.", Author = "Nnenna Oti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Arnaldo_Tamayo_M%C3%A9ndez", Text = "Although I dreamed of flying from childhood, that was utterly unthinkable. I had to start work early, a shoeshine boy — a poor man's profession — or selling vegetables.", Author = "Arnaldo Tamayo Méndez" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tornado_outbreak_of_December_10%E2%80%9311%2C_2021", Text = "This is a particularly dangerous situation. Take cover now!", Author = "Tornado outbreak of December 10–11, 2021" },
        new Quote { Id = "https://en.wikiquote.org/wiki/No_Hard_Feelings_%282023_film%29", Text = "[sees a couple on their phone in a bedroom] Does anyone even fuck anymore?", Author = "No Hard Feelings (2023 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Rakoff", Text = "It would be peevish and ungracious after being taken to such a lovely supper in this Temple of Food, I know, but I am desperate to ask the question that begs to be posed: Just how fucking good can olive oil get?", Author = "David Rakoff" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adrian_Henri", Text = "Tonight at noonSupermarkets will advertise 3d EXTRA on everything", Author = "Adrian Henri" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Andy_Hurley", Text = "Ultimately I am an employee of a corporation, and that’s weird, and does contradict some of the things I believe in. But at the same time, I have to make a living.", Author = "Andy Hurley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stephen_A._Smith", Text = "You have haters from all walks of life. I could care less who wants me to fail. They inspire me. Motivates me.", Author = "Stephen A. Smith" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Caroline_Giuliani", Text = "Nothing I have experienced prepared me for the very public and relentless implosion of my father’s life,", Author = "Caroline Giuliani" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Elaine_Mokhtefi", Text = "For anyone living in Paris, the Algerian war was inescapable.", Author = "Elaine Mokhtefi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mpho_Morolong", Text = "Concern over Unlawful Transport Operators 22 February 2025", Author = "Mpho Morolong" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Babylon_Whores", Text = "Under the sea\nDead cities in the dark\nDreaming themselves to be\nAlive once more", Author = "Babylon Whores" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jos%C3%A9_Gea_Escolano", Text = "What kind of positive future can there be for our society? As far as the government is concerned, none.", Author = "José Gea Escolano" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Extreme_programming", Text = "Extreme Programming is the first popular methodology to view software development as an exercise in coding rather than an exercise in management.", Author = "Extreme programming" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anthony_Bourdain", Text = "I do a lot of speaking engagements and sometimes I feel like I’m being paid to curse in front of people who haven’t heard it in a while.", Author = "Anthony Bourdain" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tom_Watson%2C_Baron_Watson_of_Wyre_Forest", Text = "The EU invests £11bn a year on manufacturing innovation programmes of which 15% are invested here in the UK.", Author = "Tom Watson, Baron Watson of Wyre Forest" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Henri_Michaux", Text = "A man who knows neither how to travel nor how to keep a journal has put together this travel journal. But at the moment of signing he is suddenly afraid. So he casts the first stone. Here.", Author = "Henri Michaux" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Albertina_Luthuli", Text = "Shaun is an icon in our time. It is very inspiring to have shared these few precious moments with him today. The words that he shared are poignant with meaning as he not only understands the present but the relevance of the past", Author = "Albertina Luthuli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Max_Headroom_%28TV_series%29", Text = "Edison Carter: Control, you busy tonight? Maybe all night?\nTheora Jones (almost without hesitation): Mr. Carter, we hardly know each other.", Author = "Max Headroom (TV series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Home", Text = "Home is where the heart is.", Author = "Home" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nicole_Gaelebale", Text = "Having a dream it keeps reminding you why you started it in the first place", Author = "Nicole Gaelebale" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Martin_Gardner", Text = "A surprising proportion of mathematicians are accomplished musicians. Is it because music and mathematics share patterns that are beautiful?", Author = "Martin Gardner" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Veliswa_Mvenya", Text = "I still have wounds, they are not scars yet but I’m soldiering on.", Author = "Veliswa Mvenya" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bones_%28season_11%29", Text = "Temperance Bones Brennan: [upon Seeley Booth taking a bite of her edible, gelatinous brain mould prop] Whoa, Booth! That wasn't a model; that was an actual brain I brought back from the lab.\nSeeley Booth: Ugh, oh, God!\nTemperance Bones Brennan: Gotcha!", Author = "Bones (season 11)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Per_Kirkeby", Text = "Landscapes are about beauty and death. The only way you can define beauty.. ..is to know that death is hiding behind it. This is what haunts you when you’re doing a so-called landscape painting.", Author = "Per Kirkeby" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stick_Around_%28TV_pilot%29", Text = "[opening lines]\nElaine Keefer: [enters] Vance, what time would you like to eat Dinner tonight?\nVance Keefer: [playing a game with Andy] Don't both me; I'm trying to concentrate.\nElaine Keefer: What for? I thought you programmed Andy to lose.", Author = "Stick Around (TV pilot)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Brides_of_Fu_Manchu", Text = "As you were the leader of the rebellion, you shall be the first to go to the snakes.", Author = "The Brides of Fu Manchu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gathoni_Wa_Muchomba", Text = "It is murder to double VAT on fuel products from 8% to 16%. It means the cost of basic commodities like bread will go up from KSh 70 to KSh 120, the price of bus fare and everything that is transported will go up. The cost of living will go up and you will remember me", Author = "Gathoni Wa Muchomba" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Roy_Ascott", Text = "When art is a form of behaviour, software predominates over hardware in the creative sphere. Process replaces product in importance, just as system supersedes structure.", Author = "Roy Ascott" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Marsupilami_%281993_TV_series%29", Text = "Norman: Who are you?\nMarsupilami: I am Marsupilami. This is my gorilla pal, Maurice. A world fine PhD. That's short for Pretty Huge Dope.", Author = "Marsupilami (1993 TV series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/D%C3%A9formation_professionnelle", Text = "It is difficult to get a man to understand something, when his salary depends upon his not understanding it.", Author = "Déformation professionnelle" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Skies_of_Arcadia", Text = "Vyse: Let's keep you off the ship until tomorrow. The last thing we need is for your uncle to see you throwing up in the heat of battle.\nEnrique: Great, now you're starting to sound just like Aika...", Author = "Skies of Arcadia" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alastair_David_McPhail", Text = "We are absolutely aware of the potential for future conflict, and to be honest I think we will be lucky if we can get another two years without a return to conflict if a combination of factors is not addressed.", Author = "Alastair David McPhail" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Le_Chastelain_de_Couci", Text = "La douce voiz du louseignol sauvageQu’oi nuit et jor cointoier et tentirMe radoucist mon cuer et rassouage.Lors ai talent que chant pour esbaudir.", Author = "Le Chastelain de Couci" },
        new Quote { Id = "https://en.wikiquote.org/wiki/J._L._Mackie", Text = "There are no objective values.", Author = "J. L. Mackie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Dickens", Text = "Mr. Augustus Minns was a bachelor, of about forty as he said — of about eight-and-forty as his friends said. He was always exceedingly clean, precise, and tidy: perhaps somewhat priggish, and the most retiring man in the world.", Author = "Charles Dickens" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Infinity_Train_%28season_3%29", Text = "Simon: Why, no! What are these shoe-ez you speak of?\n[the numbers on the arm of Grace increase]\nSimon: Wow... Nice combo. Guess you win again... kneepads.\nGrace: [gasps] Ah! Ooh! You're just jealous I know how to make practical look good.", Author = "Infinity Train (season 3)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Louis_Bourdaloue", Text = "At court, far from regarding ambition as a sin, people regard it as a virtue, or if it passes for a vice, then it is regarded as the vice of great souls, and the vices of great souls are preferred to the virtues of the simple and the small.", Author = "Louis Bourdaloue" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Avak_Asadourian", Text = "We are citizens of Iraq and we have been in this land, our home, for millennia. Politicians leading the country say they hope that Christians will remain in the country and continue to contribute. We ask them not to remain in good intentions, but to put them into practice through works.", Author = "Avak Asadourian" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shamim_Malende", Text = "The most important thing is to manage and keep time for home, work politics, parents and family. I allocate time. I don’t carry politics home unless I am seeking guidance or advice,", Author = "Shamim Malende" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Two_Gentlemen_of_Verona", Text = "Home-keeping youth have ever homely wits.", Author = "The Two Gentlemen of Verona" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eug%C3%A8ne_Burnouf", Text = "We will study India with its philosophy and its myths, its literature, its laws and its language. Nay It is more than India it IS a page of the origin of the world that we will attempt to decipher.", Author = "Eugène Burnouf" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jerry_R._Ehman", Text = "A person not familiar with all of the special knowledge about a particular instrument should not try to draw too many conclusions from printed data. Such data typically contains certain assumptions about the equipment not necessarily known to outsiders.", Author = "Jerry R. Ehman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abhorrence", Text = "But disguise of every sort is my abhorrence.", Author = "Abhorrence" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Catherine_Lamwaka", Text = "I am a married woman and I have children of my own and many whom am sponsoring in various schools including 23 girls and six boys. I feel I have a responsibility as a parent and a leader, when I come across a young person getting to do wrong things", Author = "Catherine Lamwaka" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fornication", Text = "Þe fyrst ys ‘fornycacyoṅ’,Whan two vnweddyd haue mysdoṅ,As sengle knaue and sengle tarne,Whan þey synne to-gedyr ȝerne;Þe leste hyt ys of allë seuene,Ȝyt hyt forbarreþ þe blys of heuene", Author = "Fornication" },
        new Quote { Id = "https://en.wikiquote.org/wiki/In_Society", Text = "Lady, he ain't dead, he's hiding!", Author = "In Society" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Total_Drama_Island_%282023%29", Text = "Emma: [enraged when she sees Chase] What is he doing here?!\nChase: Babe?\n[Emma furiously tries to attack him, but Chris holds her back]\nBowie: Ooh, I like this one.", Author = "Total Drama Island (2023)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Julia_Angwin", Text = "Objectivity has been the lodestar for journalism for a long time, and there’s a lot of legitimate reasons that people wanted to have a feeling of fairness and neutrality in the journalism that they’re reading.", Author = "Julia Angwin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Climax", Text = "[after strangling Marcellina] We'll always be together now. Your voice will never come between us again.", Author = "The Climax" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Antisthenes", Text = "It is better to fall in with crows than with flatterers; for in the one case you are devoured when dead, in the other case while alive.", Author = "Antisthenes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Khums", Text = "They ask thee concerning (things taken as) spoils of war. Say: (such) spoils are at the disposal of Allah and the Messenger: So fear Allah, and keep straight the relations between yourselves: Obey Allah and His Messenger, if ye do believe.", Author = "Khums" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jos%C3%A9_Mar%C3%ADa_Ortega_Trinidad", Text = "Pastoral work demands time, catechesis, accompaniment. Now when I travel through the prelature of Juli I realise the need for evangelisation to make Christ and the beauty of the Christian life known. We must evangelise with perseverance.", Author = "José María Ortega Trinidad" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Nostalgia_Critic/Season_8", Text = "Voice 1: It's not possible.\nVoice 2: It is.\nVoice 1: I don't believe you.\nVoice 2: Believe it.\nVoice 1: I can't believe after all these years I'm finally discovering the truth!\nVoice 2: Well, it is true.\nVoice 1: [He is Chester A Bum] You don't like The Matrix!", Author = "The Nostalgia Critic/Season 8" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Blue_Jasmine", Text = "Who do you have to sleep with around here to get a Stoli martini with a twist of lemon?", Author = "Blue Jasmine" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rayman_Brain_Games", Text = "If you want to crawl under the bongo berries, use the down arrow and the jump button or key at the same time.", Author = "Rayman Brain Games" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rick_and_Morty_%28season_5%29", Text = "Morty: So time moves faster in there? It's like a Narnia thing?\nRick: I'm not a beaver who believes in Jesus Christ, Morty... but yeah, it's pretty much a Narnia thing.", Author = "Rick and Morty (season 5)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sebastiane", Text = "Roll up, roll up! The Vestal Virgins versus the Sabine women. A glorious rape in colour.", Author = "Sebastiane" },
        new Quote { Id = "https://en.wikiquote.org/wiki/August_Krogh", Text = "For a large number of problems there will be some animal of choice or a few such animals on which it can be most conveniently studied.", Author = "August Krogh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Guchi_%28musician%29", Text = "You know every parent would definitely be scared especially when you’re a girl child. Because they feel like you will just go astray. But you know when you disappoint them and let them know that there is more to what you think then, they don’t have a choice but to love what you do.", Author = "Guchi (musician)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gifts", Text = "Health is the greatest gift, contentment is the greatest wealth, a trusted friend is the best relative, Nibbana is the greatest bliss.", Author = "Gifts" },
        new Quote { Id = "https://en.wikiquote.org/wiki/JAG_%28season_10%29", Text = "Commander Turner: [speaking to Lt. Cmdr. Bud Roberts] ... for a mild-mannered guy you sure do piss a lot of people off.", Author = "JAG (season 10)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cornelio_Fabro", Text = "Freedom, observes the philosopher, is potential launched into infinity.", Author = "Cornelio Fabro" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chidiebere_Ibe", Text = "A lot of people called and were actually crying. I feel very emotional. People saw themselves and were able to see their skin.", Author = "Chidiebere Ibe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mobile_Suit_Gundam_Wing", Text = "Heero Yuy: [to Relena] I'll kill you.", Author = "Mobile Suit Gundam Wing" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jacob_Leupold", Text = "Most often it is the case that people know that something big can be manipulated with it [i.e., the screw], but not how and in what way it is connected to time, and that untold time, and finally such force of machines, wheels, and shafts is necessary as cannot be produced nor be had.", Author = "Jacob Leupold" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Unbreakable_%28film%29", Text = "I see guys like you all the time in my work, you find someone you want to take advantage of, you tell them a fantastic story, and somewhere in there you say it, I just need your credit card number. A small down payment.", Author = "Unbreakable (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Friedrich_Feuerbach", Text = "No salvation outside of humanity! These words contain the whole of the religion of the future.", Author = "Friedrich Feuerbach" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Party_Central", Text = "[last lines; in the post-credits scene]\nMom: Timmy? Can we sleep with you tonight?\nDad: There's monsters in our closet!\nTimmy: That's what I've been trying to tell you!", Author = "Party Central" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Exploitation", Text = "The will of the capitalist is certainly to take as much as possible. What we have to do is not to talk about his will, but to enquire about his power, the limits of that power, and the character of those limits.", Author = "Exploitation" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Billy_Wilder", Text = "An actor entering through the door, you've got nothing. But if he enters through the window, you've got a situation.", Author = "Billy Wilder" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tom_R._Burns", Text = "In sum, social actors knowledgeably and actively use, interpret and implement rule systems. They also creatively reform and transform them. In such ways they bring about institutional innovation and transformation and shape the ‘deep structures’ of human history.", Author = "Tom R. Burns" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Cruel_Sea_%281953_film%29", Text = "This is a story of the Battle of the Atlantic, the story of an ocean, two ships and a handful of men. The men are the heroes. The heroines are the ships. The only villain is the sea—the cruel sea—that man has made more cruel.", Author = "The Cruel Sea (1953 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Heath_Ledger", Text = "I'm not good at future planning. I don't plan at all. I don't know what I'm doing tomorrow. I don't have a day planner and I don't have a diary. I completely live in the now, not in the past, not in the future.", Author = "Heath Ledger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Georg_Trakl", Text = "Nur dem, der Glück verachtet, wird Erkenntnis.", Author = "Georg Trakl" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Makran", Text = "Hiuen Tsang considered the script which was in use in Makran to be 'much the same as India', but the spoken language 'differed a little from that of India.'", Author = "Makran" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Marlene_Dumas", Text = "I have always been interested in how you can depict suffering without being heavy-handed", Author = "Marlene Dumas" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Improvement", Text = "Never will your striving for that which improves you and earns divine reward be wasted.", Author = "Improvement" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Wheeler_%28computer_scientist%29", Text = "Any problem in computer science can be solved with another level of indirection.", Author = "David Wheeler (computer scientist)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Leyden", Text = "Alas! that Scottish maid should sing The combat where her lover fell!That Scottish Bard should wake the string, The triumph of our foes to tell!", Author = "John Leyden" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nicole_Dubuc", Text = "When you get to do a one-shot, the whole world is open to you. It’s almost harder to decide what story to tell when you have the freedom to do anything you want!", Author = "Nicole Dubuc" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Malebogo_Marumoagae", Text = "Our main aim is to teach them about confidence and to boost their self-esteem. The programme teaches them to know who they are and to believe in themselves.", Author = "Malebogo Marumoagae" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Dale", Text = "Management policies and the quality of leadership have a lot to do with individual performance.", Author = "Ernest Dale" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Serara_Selelo-Mogwe", Text = "In order to be accepted to become a nurse, you first had to prove you were a failure!", Author = "Serara Selelo-Mogwe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Palestine", Text = "I have come bearing an olive branch and freedom fighter's gun. Do not let the olive branch fall from my hands.", Author = "Palestine" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ancient_Egypt", Text = "[In the 7th century BC] the past was supreme; the priest who cherished it lived in a realm of shadows, and for the contemporary world he had no vital meaning.", Author = "Ancient Egypt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Beto_O%27Rourke", Text = "Punk rock, at its best, was just stripping down all the corporate rock I was hearing on the radio in the 1980s and getting down to its most basic roots.", Author = "Beto O'Rourke" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Artificial_intelligence", Text = "Regulation will be crucial, and it will take time to understand this. Although the artificial intelligence tools of our generation are not particularly frightening, I think that we are not so far away from those that could potentially be.", Author = "Artificial intelligence" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Layla_Moran", Text = "David T. C. Davies [then Conservative MP for Monmouth]: I hear what the hon. Lady is saying. May I bluntly ask her whether she would be happy sharing a changing room with somebody who was born male and had a male body?", Author = "Layla Moran" },
        new Quote { Id = "https://en.wikiquote.org/wiki/No_Mean_City", Text = "Battles and sex are the only free diversions in slum life. Couple them with drink, which costs money, and you have the three principal outlets for that escape complex which is for ever working in the tenement dweller’s subconscious mind.", Author = "No Mean City" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lami_Adamu_Lau", Text = "I want to thank you mah and all your executives for putting up this not only for civil women, but for all Nigerian women..", Author = "Lami Adamu Lau" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Woit", Text = "We have an incredibly successful theory called the Standard Model. ... It still leaves open several questions.", Author = "Peter Woit" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Witnesses", Text = "There must be four witnesses to testify against the adulterer. They must testify that they saw them having sex.", Author = "Witnesses" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pialuisa_Bianco", Text = "To change one’s mind — Pialuisa Bianco states — is an absolute right. It has no adjectives.", Author = "Pialuisa Bianco" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Population_decline", Text = "The ultimate measure of human success is not production but reproduction. Economic productivity and profit are means to reproductive ends, not ends in themselves.", Author = "Population decline" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mustafa_Kemal_Atat%C3%BCrk", Text = "Men, I am not ordering you to attack. I am ordering you to die. In the time that it takes us to die, other forces and commanders can come and take our place.", Author = "Mustafa Kemal Atatürk" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Opposition_research", Text = "Quotes are arranged alphabetically per author.", Author = "Opposition research" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ayumi_Hamasaki", Text = "It is necessary that I am viewed as a product. I am a product.", Author = "Ayumi Hamasaki" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Bossie", Text = "I say to those liberals hell-bent on restricting speech: rather than trying to silence voices and viewpoints you disagree with, join the debate.", Author = "David Bossie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Raja_Chatila", Text = "Responsible AI is artificial intelligence that must be designed responsibly by humans in a way that respects human values and the environment, throughout the systems’ life cycle. All stakeholders involved must be responsible.", Author = "Raja Chatila" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alexandra_Rojas", Text = "Our goal is to build a really united cohort of progressive lawmakers in Congress who can shift the national conversation and neutralize the false populism of the far right and push visionary legislation", Author = "Alexandra Rojas" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Unconscious", Text = "The poets and philosophers before me discovered the unconscious; what I discovered was the scientific method by which the unconscious can be studied.", Author = "Unconscious" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gravitational_wave", Text = "Ladies and gentlemen, we have detected gravitational waves. We did it!", Author = "Gravitational wave" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eric_Garcia", Text = "When Melinda filed for divorce, she wrote down only two words as her reason for seeking a dissolution of our two-year marriage: Incontrovertibly self-absorbed. Or is that three words? No matter. The question I have is: Did she mean me or her?", Author = "Eric Garcia" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jewish_proverbs", Text = ".נפלה האבן על הקדרה, אוי לקדרה. נפלה הקדרה על האבן, אוי לקדרה", Author = "Jewish proverbs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Taryn_Manning", Text = "Maybe my face is edgy, but that's because it's the face of somebody who's seen life.", Author = "Taryn Manning" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Philip_Rosedale", Text = "It's a bit like The Matrix... We provide the land, and the community builds the actual world, which gives everyone a huge sense of being pioneers in a great experiment.", Author = "Philip Rosedale" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Le_M%C3%A9nagier_de_Paris", Text = "Seldom will you see ever so old a man who will not marry a young woman.", Author = "Le Ménagier de Paris" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Antoine_de_Rivarol", Text = "Les idées sont des fonds qui ne portent intérèt qu'entre les mains du talent.", Author = "Antoine de Rivarol" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christy_Ucheibe", Text = "After every tough game, you just have to get over it. There are things you can’t control, and I try to focus on the ones I can. It’s okay to reflect and work on your performance, but the key is to move ahead.", Author = "Christy Ucheibe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dick_Tracy%27s_Dilemma", Text = "Jigger: Find what you're lookin' for, Tracy?\nDick Tracy: No... and see that I don't. I understand Hatchet Harry has been hangin' around here.\nJigger: Why, that's a big mistake! Say, you know I run a respectable joint.", Author = "Dick Tracy's Dilemma" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Doug_Dorst", Text = "Of course there is a monkey. There is always a monkey.", Author = "Doug Dorst" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Silver_Jews", Text = "I’m gonna shine out in the wild kindness and hold the world to its word.", Author = "The Silver Jews" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jocelyn_Bell_Burnell", Text = "The girls got sent to the domestic science room and the boys to the science lab. ... I protested — unsuccessfully.", Author = "Jocelyn Bell Burnell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ali_Zayn_al-Abidin", Text = "If people realize the value of science and knowledge, they will sacrifice themselves for earning it.", Author = "Ali Zayn al-Abidin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Miranda_Otto", Text = "I try not to judge characters. You really have to just be inside it, seeing it from their point of view", Author = "Miranda Otto" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Al-Suyuti", Text = "It (Qur'an) is inimitable because of its eloquence, its unique style, and because it is free of error.", Author = "Al-Suyuti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Latonia_Harris", Text = "I share my story because it’s important that you understand me and the value I place on learning and formal education", Author = "Latonia Harris" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Clarence_%28American_TV_Series%29", Text = "Clarence: [riding with Amy on her bike] Hi, Mrs. Baker.\nMrs. Baker: [Screams] Hi, Clarence.\n[Chad is at the arcade]\nClarence: Chad! Chad! Chad!\nChad: Clarence! Clarence! Clarence!\nAmy: Wow.", Author = "Clarence (American TV Series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/February_18", Text = "DOB: Nikos Kazantzakis · Toni Morrison · Yoko Ono · Ramakrishna · John Travolta · Wendell Willkie", Author = "February 18" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tom_Carroll_%28surfer%29", Text = "Now I have no idea how this has come about - probably a rumour spread by my enemies - but apparently there's a general belief among some sections of the surf community that I am a bit of a drop-in artist.", Author = "Tom Carroll (surfer)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bernie_Ecclestone", Text = "The banks don't have anything - no rights whatsoever. The banks are shareholders of SLEC, and SLEC has no rights. ... I am the CEO of Formula One Management and Formula One Administration, which runs the business in F1. From this point of view, I own F1.", Author = "Bernie Ecclestone" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pluralism", Text = "Tolerance, openness and understanding towards other peoples' cultures, social structures, values and faiths are now essential to the very survival of an interdependent world.", Author = "Pluralism" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sword_Art_Online%3A_Hollow_Fragment", Text = "Philia: Sometimes I feel so empty, and so incomplete... A Hollow Fragment, I guess you could say... But with you, Kirito, I feel complete. You fill the void inside me.", Author = "Sword Art Online: Hollow Fragment" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nicole_M._Joseph", Text = "When I was a younger student, I was that kid who was able to do school. I knew how to talk to the right people and figure out what classes and things that I needed. That’s not because I had a legacy family that all went to college.", Author = "Nicole M. Joseph" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Significance", Text = "Any author who uses mathematics should always express in ordinary language the meaning of the assumptions he admits, as well as the significance of the results obtained. The more abstract his theory, the more imperative this obligation.", Author = "Significance" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Titanic_%281953_film%29", Text = "[to Julia] Twenty years ago I made the unpardonable error of thinking I could civilize a girl who bought her hats out of a Sears-Roebuck catalog.", Author = "Titanic (1953 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Captain_Disillusion", Text = "Consider the possibility that the low resolution web video is simply not detailed enough to draw a solid conclusion.", Author = "Captain Disillusion" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jacques_Danka_Longa", Text = "The objective is to help each priest to live his ministry as a means of sanctification, and to lead the people of the faithful to follow our model, Jesus Christ.", Author = "Jacques Danka Longa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shutter_Island_%28film%29", Text = "After she tried to kill herself the first time, Dolores told me she... she had an insect living inside her brain. She could feel it clicking across her skull, just... pulling the wires, just for fun. She told me that. She told me that but I didn't listen. I loved her so much.", Author = "Shutter Island (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Occleve", Text = "If that thise men that lovers hem pretende,To women weren feythfull good and trewe,And dreden hem to deceyven or offende,Women, to love hem, wolde nat eschewe;But every day hath man an herte newe:Yt, upon oon, abide can no while.What fore ys it, swich a wight to be-gile?", Author = "Thomas Occleve" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rachel_Yankey", Text = "You have to stand there against people who are probably not supporting women's football and tell them you need more money. That, in itself, takes a lot of guts. At that point, it wasn't easy to win people over.", Author = "Rachel Yankey" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Book_of_Isaiah", Text = "שָׂרַ֣יִךְ סֹורְרִ֗ים וְחַבְרֵי֙ גַּנָּבִ֔ים כֻּלֹּו֙ אֹהֵ֣ב שֹׁ֔חַד וְרֹדֵ֖ף שַׁלְמֹנִ֑ים יָתֹום֙ לֹ֣א יִשְׁפֹּ֔טוּ וְרִ֥יב אַלְמָנָ֖ה לֹֽא־יָבֹ֥וא אֲלֵיהֶֽם׃ פ", Author = "Book of Isaiah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Justin_Jin", Text = "You can watch the funniest, most popular meme and it has just come from an individual.", Author = "Justin Jin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jeremy_Hardy", Text = "It seems a shallow observation, but… the Tory Conference are not an attractive lot, are they? I mean, if all those people were born in the same village, you'd blame pollution, wouldn't you?", Author = "Jeremy Hardy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Monsters_vs._Aliens", Text = "The Omega Quadrant? Lame!", Author = "Monsters vs. Aliens" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Zanana_Akande", Text = "Both of my parents were interested in politics, but it was really my father who encouraged us from a very young age to watch the news and consider why certain decisions were being made.", Author = "Zanana Akande" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Val_Logsdon_Fitch", Text = "But mainly I learned, in approaching the measurement of new phenomena, not just to consider using existing apparatus but to allow the mind to wander freely and invent new ways of doing the job.", Author = "Val Logsdon Fitch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Laura_Coates", Text = "Democracy is absolutely in peril, not only because of the big lie that's questioned the integrity of our electoral system, but also because it's a lie that jurisdictions were, in fact, believing - that there was widespread voter fraud.", Author = "Laura Coates" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Peter_Zenger", Text = "Entitle us to the Liberty of proving the Truth of the Papers, which in the Information are called false, malicious, seditious and scandalous.", Author = "John Peter Zenger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Indian_cuisine", Text = "Ibn Battuta’s description of the preparation of samosa would make one’s mouth water even today: Minced meat cooked with almond, walnut, pistachios, onion and spices placed inside a thin bread and fried in ghee.", Author = "Indian cuisine" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Washington_Allston", Text = "Thus falling, falling from afar,As if some melancholy starHad mingled with her light her sighs,And dropped them from the skies.", Author = "Washington Allston" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vimalakirti_Sutra", Text = "Reverence to all Buddhas, Bodhisattvas, Aryasravakas, and Pratyekabuddhas, in the past, the present, and the future.", Author = "Vimalakirti Sutra" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ningishzida", Text = "Hero, lord of field and meadow, lion of the distant mountains!Ninjiczida, who brings together giant snakes and dragons!Great wild bull who, in the murderous battle, is a flood!", Author = "Ningishzida" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Heinrich_B%C3%B6ll", Text = "Eine Familie, die keine schwarzen Schafe hat, ist keine charakteristische Familie.", Author = "Heinrich Böll" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Monique_Zaahl", Text = "This is really cutting-edge stuff... it's very exciting, for me as a geneticist, what can be done.", Author = "Monique Zaahl" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Agn%C3%A8s_Ntamabyaliro_Rutagwera", Text = "Avant de tuer les femmes, vous devez les violer .", Author = "Agnès Ntamabyaliro Rutagwera" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_355", Text = "[To Mace] That's what we do, right? We put ourselves in danger so that others are not. We all look different, speak different, but we are the same.", Author = "The 355" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rope_%28film%29", Text = "The good Americans usually die young on the battlefield, don't they? Well, the Davids of the world merely occupy space, which is why he was the perfect victim for the perfect crime.", Author = "Rope (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mr._Wrong", Text = "Okay, Whitman's records. Lived with his mother until about six months ago. Had one serious relationship with an Inga... Gunther who once tried to assassinate the rock temptress... STEVIE NICKS!", Author = "Mr. Wrong" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dragon_Quest_IX", Text = "Hello? Is there anybody there?If you're there, say something. Show yourself.Thus do the voices of the mortals plead, ever hopeful for proof of our existence...For how long now have we watched over their realm...?For how long have we Celestrians existed...?", Author = "Dragon Quest IX" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Johannes_Secundus", Text = "Mensura rebus est sua dulcibus.Ut quodque mentes suavius afficit, fastidium sic triste secum limite proximiore ducit.", Author = "Johannes Secundus" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mark_Feuerstein", Text = "Is it so simple or so black and white that rich people are just kind of inherently bad? And it’s obviously not the case.", Author = "Mark Feuerstein" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Theo_Jansen", Text = "The walls between art and engineering exist only in our minds, and few go beyond them.", Author = "Theo Jansen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chester_W._Nimitz", Text = "We shall never forget that it was our submarines that held the lines against the enemy while our fleets replaced losses and repaired wounds.", Author = "Chester W. Nimitz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Glee_%28Season_1%29", Text = "Sue: High school is a caste system. Kids fall into certain slots. Your jocks and your popular kids up in the penthouse. The invisibles and the kids playing live-action out in the forest: bottom floor.\nWill: And... where do the Glee kids lie?\nSue: Subbasement.", Author = "Glee (Season 1)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hardcore_punk", Text = "Defining hardcore is like defining falling in love -- definitions really miss the point. You don't need a definition to know if you're in love or not -- you just know it. You just feel real hardcore when you experience it.", Author = "Hardcore punk" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_of_the_Cells", Text = "Wortley, John (2014). Give Me a Word: The Alphabetical Sayings of the Desert Fathers. Yonkers, New York: St. Vladimir's Seminary Press. ISBN 978-0-88141-497-4.", Author = "Isaac of the Cells" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oceanne_Iradukunda", Text = "If I wasn’t strong, I could have given up a long time ago.", Author = "Oceanne Iradukunda" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Full_House/Season_4", Text = "Papouli: [talks about a traditional wedding from his town] According to Pompadour's tradition, they are married. You give the girl flowers, you walk her around the table and... that's what it's all about.\nDanny: That's not a wedding, that's the Hokey-Pokey.", Author = "Full House/Season 4" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Book_of_Baruch", Text = "The Lord will give us strength, and light to our eyes; we shall live under the protection of King Nebuchadnezzar of Babylon, and under the protection of his son Belshazzar, and we shall serve them many days and find favor in their sight.", Author = "Book of Baruch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dead_Space_%282008_video_game%29", Text = "[Opening lines] Isaac. It's me. I wish I could talk to you. I'm sorry. I'm sorry about everything. I wish I could just talk to someone. It's all falling apart here. I can't believe what's happening. It's strange… such a little thing…", Author = "Dead Space (2008 video game)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Winx_Club_%28season_7%29", Text = "Faragonda: And along the Keepers, a friend of yours will also be joining us.\nWinx Club: Roxy!\nRoxy: Hey, girls.\nFaragonda: I thought, who better than the Fairy of Animals to get the Kangormai safely back to the park?", Author = "Winx Club (season 7)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tolu_Bally", Text = "Keep Believing In Your Self; You will Do Great Things.", Author = "Tolu Bally" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Easton", Text = "Political science is the study of the authoritative allocation of values for a society.", Author = "David Easton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/J._Michael_Bailey", Text = "Homosexuality might be the most striking unresolved paradox of human evolution.", Author = "J. Michael Bailey" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Serer_people", Text = "Senegalese music has very diverse traditions, drawing on Serer, Fula and Casamance influences.", Author = "Serer people" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Basil_Bhuriya", Text = "We face constant harassment and persecution. The need of the hour is to address people's grievances and establish rapport with political parties of different ideologies to safeguard our people's interest.", Author = "Basil Bhuriya" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dirkie_Chamberlain", Text = "I have lived my childhood dream and given everything I could to the badge. Every match, every moment, and every experience has been a privilege that I will cherish forever.", Author = "Dirkie Chamberlain" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Printing", Text = "He who first shortened the labor of Copyists by device of Movable Types was disbanding hired Armies and cashiering most Kings and Senates, and creating a whole new Democratic world: he had invented the Art of printing.", Author = "Printing" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thelma_%26_Louise", Text = "I've had it up to my ass with sedate.", Author = "Thelma & Louise" },
