        new Quote { Id = "https://en.wikiquote.org/wiki/Allan_Cunningham", Text = "A wet sheet and a flowing sea, A wind that follows fast,And fills the white and rustling sail, And bends the gallant mast.And bends the gallant mast, my boys, While like the eagle freeAway the good ship flies, and leaves Old England on the lee.", Author = "Allan Cunningham" },
