        new Quote { Id = "https://en.wikiquote.org/wiki/Feelings", Text = "Below the surface stream, shallow and light,Of what we say and feel—below the stream,As light, of what we think we feel, there flowsWith noiseless current, strong, obscure and deep,The central stream of what we feel indeed.", Author = "Feelings" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Justin_and_the_Knights_of_Valour", Text = "[Before the battle, when worrying about Talia] What I mean is, I don't want anything to happen to you.", Author = "Justin and the Knights of Valour" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_L._Lewis", Text = "I have pleaded (labor's) case, not in the quavering tones of a feeble mendicant asking alms, but in the thundering voice of the captain of a mighty host, demanding the rights to which free men are entitled.", Author = "John L. Lewis" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christelle_Yambayisa", Text = "I've always been comfortable in my skin so I never let anyone look down on me because I am a coloured woman. I would like to accredit my easy journey to the level of education and literacy of the environment I am in.", Author = "Christelle Yambayisa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pamela_Nomvete", Text = "My self-esteem was rock bottom and sinking. Slowly‚ I was just being broken down. Everything was going out and nothing was going in. I wasn’t nurturing Pamela. By the time my partner decided to move his whole family into my house‚ Pamela was gone and I was asking myself who am I?", Author = "Pamela Nomvete" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Audrey_Mbugua", Text = "I don't think it represented the entire gamut of the conflict between transgender people and a few confused groups. There are millions of Kenyan Christians who respect me and the entire transgender struggle.", Author = "Audrey Mbugua" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Grimes", Text = "Peter Grimes, a fisherman", Author = "Peter Grimes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Boreanaz", Text = "It's definitely a beautiful blonde with dirty underwear.", Author = "David Boreanaz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Last_words_in_Transformers_media", Text = "Until that day...till all are one.", Author = "Last words in Transformers media" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Monique_S%C3%A9ka", Text = "I dream of playing wherever I am asked. Where the public calls for me. The question would be why the promoters took so long to invite me? But as they say everything is won in teams.", Author = "Monique Séka" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Giovanni_Maria_Vian", Text = "What binds me to my grandfather is certainly intransigent fidelity to the Holy See – naturally without indulging in the obsequiousness that can reach sickly forms of popolatry – and a conscience that must always remain on the alert.", Author = "Giovanni Maria Vian" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Frank_Harris", Text = "Strong men are made by opposition; like kites they go up against the wind.", Author = "Frank Harris" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bhogeswar_Baruah", Text = "How do I describe my feelings? How does anyone describe these emotions? It is like a big emptiness. Perhaps, it is same emotion-filled empty feeling a father experiences the day after the marriage of his daughter", Author = "Bhogeswar Baruah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/September_22", Text = "4. David | Talk 21:02, 10 September 2006 (UTC)", Author = "September 22" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Moore", Text = "Faintly as tolls the evening chime,Our voices keep tune and our oars keep time.", Author = "Thomas Moore" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Closer_%282004_film%29", Text = "Lying is the most fun a girl can have without taking her clothes off... but it's better if you do.", Author = "Closer (2004 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tides", Text = "There is symbolic as well as actual beauty in the migration of birds, in the ebb and flow of the tides; in the folded bud ready for the spring. There is something infinitely healing in these repeated refrains of nature-the assurance that dawn comes after night, and spring after winter.", Author = "Tides" },
        new Quote { Id = "https://en.wikiquote.org/wiki/East_of_Eden_%28film%29", Text = "Son, I'd be happy if you'd give me something like your brother's given me. Something honest and human and good. Don't be angry, Son. If you want to give me a present, give me a good life. That's something I could value.", Author = "East of Eden (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Verna_Sinimbo", Text = "It is a place where ancient traditions co-exist with a rapidly- evolving modern world. These indigenous natural resources are in demand and are often part of the ingredients in food, supplements, cosmetics and medicines", Author = "Verna Sinimbo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lion_Feuchtwanger", Text = "Without darkness there would be no concept of light For light to be self aware it must have its opposite—darkness.", Author = "Lion Feuchtwanger" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Personal_property", Text = "I talk half the time to find out my own thoughts, as a school-boy turns his pockets inside out to see what is in them. One brings to light all sorts of personal property he had forgotten in his inventory.", Author = "Personal property" },
        new Quote { Id = "https://en.wikiquote.org/wiki/82nd_Airborne_Division", Text = "In the draft of 1917, a man from Tennessee Overseas to the trenches he went, from the land of the free Into war he brought two things along, a rifle and his faith Joined the ranks as a private, assigned to 338th There on that day Alvin York entered the fray Saving the day 82nd all the way!", Author = "82nd Airborne Division" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_Graham%2C_1st_Marquess_of_Montrose", Text = "He either fears his fate too much, Or his deserts are small,That dares not put it to the touch To gain or lose it all.", Author = "James Graham, 1st Marquess of Montrose" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Philip_Gibbs", Text = "It's better to give than to lend, and it costs about the same.", Author = "Philip Gibbs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kenza_Dali", Text = "But football was never my main goal as a kid, it was simply a joy, also because back then there weren’t many chances to make a living out of football as a woman.", Author = "Kenza Dali" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Niall_Ferguson", Text = "The First World War was at once piteous, in the poet's sense, and 'a pity'. It was something worse than a tragedy, which is ultimately something we are taught by the theatre to regard as unavoidable. It was nothing less than the greatest error of modern history.", Author = "Niall Ferguson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Ross_Wallace", Text = "They say that man is mighty,He governs land and sea;He wields a mighty scepterO'er lesser powers than he; But a mighty power and stronger, Man from his throne hath hurled, For the hand that rocks the cradleIs the hand that rules the world.", Author = "William Ross Wallace" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Puss_in_Boots_%282011_film%29", Text = "[first lines; voice over] Through the years, I have been known by many names. Diablo Gato, The Furry Lover, Frisky Two Times, and then The Gingerhead Man. But to most, I am Puss in Boots! [whispers] Outlaw.", Author = "Puss in Boots (2011 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Enoch_Crowder", Text = "Arthur MacArthur was the most flamboyantly egotistical man I had ever seen, until I met his son.", Author = "Enoch Crowder" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Hurt", Text = "It's reasonable to offer benefits.", Author = "Robert Hurt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Naval_architecture", Text = "The shipbuilder, caulking a boat, heating up fish oil, with garments not easy to clean.", Author = "Naval architecture" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_V%2C_Holy_Roman_Emperor", Text = "My life has been one long journey.", Author = "Charles V, Holy Roman Emperor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mohamad_Sabu", Text = "Thus far, they (Eastern Sabah Security Command security forces) have performed their best and we need to increase their welfare. This is my determination along with the army, police and other enforcement bodies to intensify their service together.", Author = "Mohamad Sabu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Horror", Text = "I will make this city an object of horror and something to whistle at. Every last one passing by it will stare in horror and whistle over all its plagues.", Author = "Horror" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alimotu_Pelewura", Text = "I am she who is called Pelewura…. . I will not starve in the country I was born in.", Author = "Alimotu Pelewura" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ohemaa_Adjei_Andoh", Text = "I will say my greatest achievement has been the ability to tailor my passion to help the younger generation through STEM. That is through GIST and PM STEAM Academy.", Author = "Ohemaa Adjei Andoh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_Franco", Text = "I'm gay in my art and straight in my life.", Author = "James Franco" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fifteenth_Doctor", Text = "The Fourteenth Doctor: You're me!\nThe Doctor: No, I'm me... I think I'm really, really me! Oh-ho, I am completely me!", Author = "Fifteenth Doctor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mary_Bono", Text = "As Chair and CEO of Mothers Against Prescription Drug Abuse, I am happy to lend my voice to the important work underway.", Author = "Mary Bono" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kenneth_Francis_Hackett", Text = "No government agrees with another government on everything.", Author = "Kenneth Francis Hackett" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Burna_Boy", Text = "No evidence, you go explain tire", Author = "Burna Boy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Nostalgia_Critic/Season_11", Text = "[A real life Lara Croft appears in front of Critic, looking EXACTLY like the PlayStation character]\nNostalgia Critic: Oh, your smooth pointy face, your terrifyingly large lips, and your breasts. Oh, so square.\nLara: You know nothing will ever be sexier than me.\nNostalgia Critic: Never. Never!", Author = "The Nostalgia Critic/Season 11" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_W._Panuelo", Text = "It is imperative that we show our friends (Samoa), especially during their darkest hours, that we stand with them. Recent weeks have been very troubling for the Samoan People, who have been witnessing what is arguably a constitutional and political crisis.", Author = "David W. Panuelo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cory_Booker", Text = "Lets you and I try to live on food stamps in New Jersey (high cost of living) and feed a family for a week or month. U game?", Author = "Cory Booker" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tariq_Rahman", Text = "Tariq Rahman - Interpretations of Jihad in South Asia_ An Intellectual History-de Gruyter (2018)", Author = "Tariq Rahman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stacy_Hardy", Text = "Finally, she looks up and asks: Do you have any pets? She doesn’t know why this question. He shakes his head. He doesn’t like the idea of animals being domesticated. He says something about corrupting the animal spirit. She says: And cockroaches?", Author = "Stacy Hardy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Phaedrus_%28fabulist%29", Text = "Fortes indigne tuliMihi insultare: te, nature dedecus,Quod ferre certe cogor, bis videor mori.", Author = "Phaedrus (fabulist)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cocoon_%28film%29", Text = "Jack Bonner: I wouldn't accuse you of dishonesty! I accuse you of being from another planet, but an honest planet!", Author = "Cocoon (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/European_robin", Text = "Ah, wretched me! he loudly cried, What is it I have done?O, would to the Powers above I’d dyed When thus I left her alone:Come, come, you gentle redbreast now, And prepare for us a tomb, Whilst unto cruel death I bow, And sing like a swan my doom.", Author = "European robin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/George_Grossmith", Text = "You should see me dance the Polka,You should see me cover the ground,You should see my coat-tails flying,As I jump my partner round;When the band commences playing,My feet begin to go,For a rollicking romping PolkaIs the jolliest fun I know.", Author = "George Grossmith" },
        new Quote { Id = "https://en.wikiquote.org/wiki/In_a_Lonely_Place", Text = "He's a smart fellow, that Lochner. A couple times, he almost had me. It was his story against mine. But, of course, I told my story better...I was smart. I covered all the angles, I have an airtight alibi.", Author = "In a Lonely Place" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Decolonization", Text = "Hostility to Enlightenment Western values is particularly characteristic of decolonisation. Alas nothing very credible have been offered in their place.", Author = "Decolonization" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bassel_Khartabil", Text = "The people who are in real danger never leave their countries. They are in danger for a reason and for that they don’t leave.", Author = "Bassel Khartabil" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Key_Largo_%28film%29", Text = "You don't like it, do you Rocco, the storm? Show it your gun, why don't you? If it doesn't stop, shoot it.", Author = "Key Largo (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Gordon_R._Dickson", Text = "Even as she lay dreaming these dreams, however, a sane part of her mind was still on duty. Realistically, she knew that what she was thinking was nonsense.", Author = "Gordon R. Dickson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fuchsia_Dunlop", Text = "Planning a good menu demands experience, a certain amount of knowledge and a good deal of thought. I'm only half-joking when I say that learning how to order well in Chinese restaurants is one of my life's proudest achievements.", Author = "Fuchsia Dunlop" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hossein_Amir-Abdollahian", Text = "Iran is seeking to consolidate its relations with its neighbor. There are no restrictions or exceptions in establishing good relations between Iran and the countries of the region.", Author = "Hossein Amir-Abdollahian" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pr%C3%A1xedis_Guerrero", Text = "La resistencia del pasivismo se revuelve ahora contra el impulso progresista de la revolución.", Author = "Práxedis Guerrero" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_McRuer", Text = "The system of compulsory able-bodiedness, which in a sense produces disability, is thoroughly interwoven with the system of compulsory heterosexuality that produces queerness.", Author = "Robert McRuer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/101_Reykjav%C3%ADk", Text = "Life is one week. I drop dead each weekend. I'll be dead after I die... and I was dead before I was born. Life is a break from death.", Author = "101 Reykjavík" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Willard_van_Orman_Quine", Text = "How are we to adjudicate among rival ontologies? Certainly the answer is not provided by the semantical formula To be is to be the value of a variable; this formula serves rather, conversely, in testing the conformity of a given remark or doctrine to a prior ontological standard.", Author = "Willard van Orman Quine" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Shining_%28film%29", Text = "God, I'd give anything for a drink. I'd give my goddamned soul for just a glass of beer.", Author = "The Shining (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/El_Elyon", Text = "וּמַלְכִּי־צֶדֶק מֶלֶךְ שָׁלֵם הוֹצִיא לֶחֶם וָיָיִן וְהוּא כֹהֵן לְאֵל עֶלְיוֹן׃‎", Author = "El Elyon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Francesca_Woodman", Text = "I feel like I am floating in plasma I need a teacher or a lover I need someone to risk being involved with me. I am so vain and I am so masochistic. How can they coexist?", Author = "Francesca Woodman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Th%C3%A9r%C3%A8se_Couderc", Text = "I understand the full extent of the expression to surrender oneself, but I cannot explain it. I only know that it is very vast, that it embraces both the present and the future.", Author = "Thérèse Couderc" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Corey_Robin", Text = "A wise psychoanalyst once told me, Stop looking at what you’re saying, look at what you’re doing.", Author = "Corey Robin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Show_Biz_Bugs", Text = "What?! The rabbit's name over mine?! I'll just see about that!", Author = "Show Biz Bugs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Victor_Hermann_Balke", Text = "All these ministries are connected in one way or another to the advancement of the Gospel and the Kingdom of God. These offices are not ends in themselves. The purpose is to help parishes spread the Gospel and build the Kingdom.", Author = "Victor Hermann Balke" },
        new Quote { Id = "https://en.wikiquote.org/wiki/My_Life_as_a_Courgette", Text = "Raymond: OK... Where's your father?\nCourgette: Here... And there's my dad's chick. Mum always said he liked chicks very much\nRaymond: Alright...", Author = "My Life as a Courgette" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_K._Kao", Text = "If you really look at it, I was trying to sell a dream … There was very little I could put in concrete to tell these people it was really real.", Author = "Charles K. Kao" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jacqueline_Mukangira", Text = "Rwanda Liberation Day is observed because it marks the end of a period under a tyrannical government, and the beginning of freedom from oppression. It represents the end of a dictatorship and the start of democracy.", Author = "Jacqueline Mukangira" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wang_Hongwen", Text = "What is wrong with rebellion? It was through the rebellion led by Chairman Mao against imperialism, feudalism and bureaucratic capitalism that members of the Communist Party of China achieved the victory of revolution and succeeded in seizing political power.", Author = "Wang Hongwen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/TY_Bello", Text = "Art is about collecting experiences and expressing them. For me music and photography are similar art forms. I collect experiences, stir them in myself and express it in my own language. Just like my photography, music is my language.", Author = "TY Bello" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Damon_Wayans", Text = "So I got diagnosed with diabetes about 10 years ago. And so I started growing fresh vegetables. I only eat my vegetables", Author = "Damon Wayans" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ameer_Haider_Khan_Hoti", Text = "We would fight against terrorism and win at any cost.", Author = "Ameer Haider Khan Hoti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abdul_Latif_Rashid", Text = "Peace and security is all over the country (Iraq), and I would be very glad if you will report that and emphasize on that, instead of giving a picture of Iraq ... still (as) a war zone, which a lot of media still do.", Author = "Abdul Latif Rashid" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Glenn_Gould", Text = "The mental imagery involved with pianistic tactilia is not related to the striking of individual keys but rather to the rites of passage between notes.", Author = "Glenn Gould" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Walter_Winchell", Text = "At the height of his popularity, in the late 1930s, 50 million people—two-thirds of American adults—read Winchell's syndicated column and listened to his Sunday-night radio broadcast.", Author = "Walter Winchell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/M%2AA%2AS%2AH_%28season_3%29", Text = "General Steele: War and whiskey don't mix! General Grant kept throwing up on his bugler.", Author = "M*A*S*H (season 3)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mimi_Fawaz", Text = "Research is very important.", Author = "Mimi Fawaz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Princess_Daisy", Text = "Don't underestimate me, people! Just because I'm a princess doesn't mean I won't fight dirty! — Fortune Street", Author = "Princess Daisy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paul_Sears", Text = "For the highest function of science is to give us an understanding of consequences.", Author = "Paul Sears" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Slaughterhouse-Five", Text = "This is a novel somewhat in the telegraphic schizophrenic manner of tales of the planet Tralfamadore, where the flying saucers come from. Peace.", Author = "Slaughterhouse-Five" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Fang_Jianping", Text = "We are asking all the faithful to pray for the victims and help survivors. As Christians, Christian charity is something we must live out. We should practice what we believe and profess.", Author = "Peter Fang Jianping" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Napoleon_III", Text = "In politics evils should be remedied not revenged.", Author = "Napoleon III" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kenan_Malik", Text = "The university is a space for would-be adults to explore new ideas, to expand their knowledge, to interrogate power, to learn how to make an argument. A space within which students can be challenged, even upset or shocked or made angry.", Author = "Kenan Malik" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adenike_Oladiji", Text = "As a university of technology, we must be prepared to deal with emerging questions that we did not know had to be answered. The COVID-19 experience showed that there is a lot of ground yet uncovered.", Author = "Adenike Oladiji" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Prowse", Text = "I mean it's wonderful to see that something you have done in your career has attracted so much attention. It was basically giving it what I call a lifetime achievement, it's something people will never forget.", Author = "David Prowse" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Westminster_Assembly", Text = "Q. What is the chief end of man? A. Man's chief end is to glorify God, and to enjoy him for ever.", Author = "Westminster Assembly" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Saving_Silverman", Text = "And a beer bong for the lady?", Author = "Saving Silverman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Car", Text = "I think cars today are almost the exact equivalent of the great Gothic cathedrals. I mean the supreme creation of an era, conceived with passion by unknown artists, and consumed in image if not in usage by a whole population which appropriates them as a purely magical object.", Author = "Car" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Peter_Schmidt_%28artist%29", Text = "You need not kill You need not steal You need not be unfaithful You need not lie You may honour your father and mother You need not desire other people's things You need not desire other people's bodies You need not make images You may rest sometimes You may love God.", Author = "Peter Schmidt (artist)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oluwayemisi_Oluremi_Obilade", Text = "Teachers should be trained and retrained. This should be done regularly. If teachers who are key factors in schools are left out, then we should not expect that pupils would perform very well.", Author = "Oluwayemisi Oluremi Obilade" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eva_Alordiah", Text = "Never believe all you hear or read about anyone.", Author = "Eva Alordiah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ryk_E._Spoor", Text = "Living creatures are essentially biological carbon-based nanotech.", Author = "Ryk E. Spoor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Manuscript_Found_in_Accra", Text = "The papyruses are Greek translations of texts written between the end of the First century BC and AD 180, and they constitute a body of work also known as the Apocryphal Gospels because they are not included in the Bible as we know it today.", Author = "Manuscript Found in Accra" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alexander_Acosta", Text = "I am deeply grateful and honored for the opportunity to serve my country. [...] I thank the President and his staff for their confidence in me and I am eager to work tirelessly on behalf of the American worker", Author = "Alexander Acosta" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Roscoe_Thayer", Text = "You shall not change, but a nobler race of menShall walk beneath the stars and wander by the shore;I can not guess their glory, but I think the sky and seaWill bring to them more gladness than they brought to us of yore.", Author = "William Roscoe Thayer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Amrita_Acharia", Text = "I love working on more intimate indie sets just as much as on the big budget show. They are very different beasts but it’s the passion for the project that makes the experiences amazing, and the talents you get to work with.", Author = "Amrita Acharia" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Raquel_Jodorowsky", Text = "Poets appeared like flowers on the earth.", Author = "Raquel Jodorowsky" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Katlego_Kai_Kolanyane-Kesupile", Text = "If there is any place I don't belong, it's in a mind where the story of me starts with the branch of me being queer and not with my rural roots.", Author = "Katlego Kai Kolanyane-Kesupile" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lisa_S._Jones", Text = "Greatness can be born from anywhere in the world and is not geographically defined", Author = "Lisa S. Jones" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rayid_Ghani", Text = "I realized two things It’s doable at the massive scale of the campaign, and that means it’s doable in the context of other problems.", Author = "Rayid Ghani" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Simpsons/Season_18", Text = "Lisa: [after Bart teases her in his spot] Otto, Bart Won't Get Me a Seat!", Author = "The Simpsons/Season 18" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jens_Spahn", Text = "The health of the population (due to COVID-19 outbreaks) takes precedence over economic interest.", Author = "Jens Spahn" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oldboy_%282003_film%29", Text = "When the melody turns on, gas comes out. When the gas comes out, I fall asleep. I found out later it's the same Valium gas the Russians used on those Chechen terrorists.", Author = "Oldboy (2003 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Harley_Davidson_and_the_Marlboro_Man", Text = "Oh God, if you're up there, looking down from wherever it is you look down from... look away now.", Author = "Harley Davidson and the Marlboro Man" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Commutative_algebra", Text = "It has seemed to me for a long time that commutative algebra is best practiced with knowledge of the geometric ideas that played a great role in its formation: in short, with a view toward algebraic geometry.", Author = "Commutative algebra" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Riyad_Naasan_Agha", Text = "The so-called Al-Qaeda is, in my opinion, an illusion. It is a bunch of organizations which used to be supervised by the CIA, and used to commit crimes in some Arab and Islamic countries.", Author = "Riyad Naasan Agha" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Out_Cold_%282001_film%29", Text = "[girl in bed with him farts on him] Oh, no you didn't.", Author = "Out Cold (2001 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anita_Bowser", Text = "As a State Senator she tried to remain accessible to the citizens she represented.", Author = "Anita Bowser" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tomato-gate", Text = "It’s the first time [the show’s] been hosted by a couple of tomatoes!", Author = "Tomato-gate" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Autobiography_of_Mark_Twain", Text = "The only reason why God created man is because he was disappointed with the monkey.", Author = "Autobiography of Mark Twain" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cleanliness", Text = "Todo saldrá en la colada.", Author = "Cleanliness" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Michels", Text = "Historical evolution mocks all the prophylactic measures that have been adopted for the prevention of oligarchy. If laws are passed to control the dominion of the leaders, it is the laws which gradually weaken, and not the leaders.", Author = "Robert Michels" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Ambrose_Jones", Text = "The maintenance of religion and its ministers in Spain and her colonies was not an act of mere piety or generosity towards the Church, but a partial and meagre compensation to the Church for repeated spoliations, particularly during the last century.", Author = "William Ambrose Jones" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Enrique_Figaredo_Alvargonz%C3%A1lez", Text = "We are here to build the common good, to build an inclusive society and bring the joy of life in Christ, everywhere, to every man and woman. As believers in the Resurrection, as men and women of hope, we are bearers of a positive vision, of hope, joy and happiness.", Author = "Enrique Figaredo Alvargonzález" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_ibn_Zakariya_al-Razi", Text = "The doctor's aim is to do good, even to our enemies, so much more to our friends, and my profession forbids us to do harm to our kindred, as it is instituted for the benefit and welfare of the human race, and God imposed on physicians the oath not to compose mortiferous remedies.", Author = "Muhammad ibn Zakariya al-Razi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Granville_Van_Dusen", Text = "I’m on the stage alone for 90 minutes. If I start mailing it in, I’m going to get lost. Part of the craft of acting is being properly prepared. I have too much respect for Lincoln to approach it any other way.", Author = "Granville Van Dusen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sarah_Bahbah", Text = "I grew up with so much guilt and shame for wanting to embody my sexuality and my identity, but I never really had a space where I fit into", Author = "Sarah Bahbah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/2013_Shapla_Square_protests", Text = "Mirza Fakhrul asked the activists to come to Dhaka with extra clothes to seize power. So do we stand to eat lollipop? We are also ready. BNP will be blocked if they block. The fate of BNP will be worse than Shapla square. Sheikh Hasina will not bow down.", Author = "2013 Shapla Square protests" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mariana_Savka", Text = "Ось Господь. Він убитий лежить у труні. Воскресіння злетіло, здається, із графіка. Він був волонтером в останній найгіршій війні.", Author = "Mariana Savka" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Suffian_Hakim", Text = "The first story I wrote was called Attack of the Giant Killer Underwear. It was about a batch of dirty underwear that got exposed to toxic radiation and grew to an enormous size. They gained sentience and travelled to Singapore, wreaking havoc along the way.", Author = "Suffian Hakim" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_W._Kingdon", Text = "It seemed to me that we knew something about how issues were decided, but that we knew much less about how they got to be issues in the first place.", Author = "John W. Kingdon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jay_W._Lorsch", Text = "When a firm chooses to allocate its most valuable resources away from clients and to young stars, the economic consequences are real and visible.", Author = "Jay W. Lorsch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Mummy%27s_Tomb", Text = "The moon rides high in the sky again, Kharis; there's death in the night air. Your work begins.", Author = "The Mummy's Tomb" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pierre_Schaeffer", Text = "Something new has been added, a new art of sound. Am I wrong in calling it music?", Author = "Pierre Schaeffer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Scrutiny", Text = "As we learn to bear the intimacy of scrutiny and to flourish within it, as we learn to use the products of that scrutiny for power within our living, those fears which rule our lives and form our silences begin to lose their control over us.", Author = "Scrutiny" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anthony_Pilla", Text = "As the parish goes, so goes the faith of the people.", Author = "Anthony Pilla" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Norah_Barlow", Text = "I retired but to be perfectly frank I was even busier than before. But it wasn’t as rewarding, I still loved management,", Author = "Norah Barlow" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Punchline_%28film%29", Text = "We are all God's animated cartoons.", Author = "Punchline (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_V_of_Kelantan", Text = "Sila duduk dan jangan berlari.", Author = "Muhammad V of Kelantan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Antonio_Ca%C3%B1izares_Llovera", Text = "If we trivialize Communion, we trivialize everything, and we cannot lose a moment as important as that of receiving Communion, of recognizing the real presence of Christ there, of the God who is the love above all loves, as we sing in a hymn in Spanish.", Author = "Antonio Cañizares Llovera" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_Beattie", Text = "When squint-eyed Slander plies the unhallow'd tongue,From poison'd maw when Treason weaves his line,And Muse apostate (infamy to song!)Grovels, low muttering, at Sedition's shrine.", Author = "James Beattie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Oby_Ezekwesili", Text = "Nigeria needs to be rescued urgently. What we see in our country is massive failure of our leaders.", Author = "Oby Ezekwesili" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nombulelo_Mabandla", Text = "For I cannot lose sight of the reality that your presence here , represent the aspiration of millions of our people across the length and breadth of our province with their hope and trust on us as elected leaders to champion their cause.", Author = "Nombulelo Mabandla" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Prodigy", Text = "Change my pitch up. Smack my bitch up.", Author = "The Prodigy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_King_and_the_Mockingbird", Text = "Sire, too late to escape now! My friends, the birds are here! And when I say birds... [the wild animals enter] I don't really mean birds!", Author = "The King and the Mockingbird" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Z_Brewer", Text = "Could you get O positive this time? That's my favorite.", Author = "Z Brewer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lin_San-quei", Text = "What we are aiming to do is to capitalize on the recruitment of foreign workers to increase employment for local workers and to enhance the nation's competitiveness.", Author = "Lin San-quei" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rehana_Akter_Ranu", Text = "The members of the government party will start jumping after reading this book.", Author = "Rehana Akter Ranu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Michael_Richards", Text = "For me to be at a comedy club and flip out and say this crap, I'm deeply, deeply sorry. … I'm not a racist, that's what's so insane about this!", Author = "Michael Richards" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Baldur%27s_Gate_3", Text = "Just give the word, and I will kill the clown. We would be praised as heroes.", Author = "Baldur's Gate 3" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jennifer_Bartlett", Text = "I can’t write myself except through reading others’ words.", Author = "Jennifer Bartlett" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tiburcio_V%C3%A1squez", Text = "I went to my mother and told her I intended to commence a different life. I asked for and obtained her blessing, and at once commenced the career of a robber.", Author = "Tiburcio Vásquez" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sodium", Text = "Sir Humphrey DavyAbominated gravy.He lived in the odiumOf having discovered sodium.", Author = "Sodium" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Amal_Ayouch", Text = "It’s refreshing to work on a film like this; there are so few movies about women’s desires and sexual needs in Morocco, as it’s the case in other Muslim countries,", Author = "Amal Ayouch" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bells", Text = "Ring out the bells again; like we did when spring began.", Author = "Bells" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Darawiish", Text = "One threat was emanating from the neighboring Suldaan Cali Yuusuf of Hoobya, and the other from the Darawiish headquarter in Beletweyne", Author = "Darawiish" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Phil_Tippett", Text = "I keep up on the news, and there's all this noise out there, with all of the media and people on their phones all the time. I think we've become a schizophrenic culture primarily as a result of the genie getting out of the bottle with all this media stuff.", Author = "Phil Tippett" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Maria_Shriver", Text = "I’m trying to take a beat to digest the Rittenhouse verdict. My son just asked me how it’s possible that he didn’t get charged for anything. How is that possible? I don’t have an answer for him.", Author = "Maria Shriver" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Coventry_Mystery_Plays", Text = "As I out rode this enderes night,Of thre ioli sheppardes I saw a sight,And all abowte there fold a star shone bright;They sange terli terlowe;So mereli the sheppards ther pipes can blow.", Author = "Coventry Mystery Plays" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Angelica_Hale", Text = "I couldn’t wait to pursue my love of singing again. Music helped me through a lot in the hospital, and it seemed like I was far away from my troubles when I was singing or listening to music.", Author = "Angelica Hale" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Disenchanted_%28film%29", Text = "I know that change can be scary, but it can also be exciting.", Author = "Disenchanted (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Annie_Ernaux", Text = "I can no longer think of any way to change my life except by having a baby. I will never sink lower than that.", Author = "Annie Ernaux" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Night_Court", Text = "Season 1\nSeason 2\nSeason 3\nSeason 4\nSeason 5\nSeason 6\nSeason 7\nSeason 8\nSeason 9", Author = "Night Court" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Grace_Jones", Text = "I was (...) determined to look the way I wanted to look, and I wanted to cut my hair. I wanted to look different because I was used to looking different. Because of my religious background I'd always been encouraged to look different.", Author = "Grace Jones" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Attila", Text = "For what fortress, what city, in the wide extent of the Roman empire, can hope to exist, secure and impregnable, if it is our pleasure that it should be erased from the earth?", Author = "Attila" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Crosby", Text = "It can't happen here is number one on the list of famous last words.", Author = "David Crosby" },
        new Quote { Id = "https://en.wikiquote.org/wiki/TaleSpin", Text = "Don Karnage: Greetings and salivations, fellow aviator. It is I, that panic provoking pirate: Don Karnage.", Author = "TaleSpin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Realpolitik", Text = "Mittel Energie auszuüben und nur ihn anzuordnen der Energie besitzt kann sie ausüben. Dieser direkte Anschluß der Energie und der Richtlinie bildet die grundlegende Wahrheit aller Politik und den Schlüssel zu aller Geschichte.", Author = "Realpolitik" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Ben-Gurion", Text = "The agricultural community that the Arabs found in Eretz Israel in the 7th century was none other than the Hebrew farmers that remained on their land despite all the persecution and oppression of the Roman and Byzantine emperors.", Author = "David Ben-Gurion" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lombard_proverbs", Text = "Buna mama a la sò s ciata Miga n vot la ga dis ciapa.", Author = "Lombard proverbs" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fran_Lebowitz", Text = "I never met anyone who didn't have a very smart child. What happens to these children, you wonder, when they reach adulthood?", Author = "Fran Lebowitz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ramsey_Clark", Text = "A right is not what someone gives you; it's what no one can take from you.", Author = "Ramsey Clark" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jackboots_on_Whitehall", Text = "My dear countrymen, dear friends. Never in the field of human conflict, was so buggered up by so few for so many!", Author = "Jackboots on Whitehall" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ling_Ma", Text = "Chicago is the most American of American cities.", Author = "Ling Ma" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ambrose_Mutinhiri", Text = "When the military took over, I found it to be very wrong", Author = "Ambrose Mutinhiri" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Koji_Wada", Text = "We may have more information about the risk of infection and the risk of severity of getting the (COVID-19) virus, so we can prepare. So we can have some precautions for infection control ... but I hope we can conduct the Tokyo Olympics as scheduled.", Author = "Koji Wada" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chief_Seattle", Text = "My people are few. They resemble the scattering trees of a storm-swept plain...There was a time when our people covered the land as the waves of a wind-ruffled sea cover its shell-paved floor, but that time long since passed away with the greatness of tribes that are now but a mournful memory.", Author = "Chief Seattle" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vilayanur_S._Ramachandran", Text = "Here is this mass of jelly - three pound mass of jelly - that you can hold in the palm of your hand, and it can contemplate the vastness of interstellar space, it can contemplate the meaning of infinity, and it can contemplate itself contemplating the meaning of infinity.", Author = "Vilayanur S. Ramachandran" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shana_Alexander", Text = "The sad truth is that excellence makes people nervous.", Author = "Shana Alexander" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Amazing_World_of_Gumball", Text = "Nicole: Go—\nGumball: to—\nDarwin: the—\nNicole: toilet.", Author = "The Amazing World of Gumball" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Paul_McCartney", Text = "She's lovely, great. She was very friendly. She was just like a mum to us.", Author = "Paul McCartney" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Victor_Osuagwu", Text = "God did not create the marriage institution for quarrelling. It is for blessing and enjoyment.", Author = "Victor Osuagwu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Smash_Mouth", Text = "All tracks are written by Greg Camp, except where noted.", Author = "Smash Mouth" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Serenity", Text = "As you cannot have a sweet and wholesome abode unless you admit the air and sunshine freely into your rooms, so a strong body and a bright, happy, or serene countenance can only result from the free admittance into the mind of thoughts of joy and good will and serenity.", Author = "Serenity" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alice_in_Wonderland_%282010_film%29", Text = "Curiouser and curiouser.", Author = "Alice in Wonderland (2010 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eraserhead", Text = "[the Baby is going into violent convulsions and has broken out in spots] Oh, you are sick!", Author = "Eraserhead" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Daniella_Okeke", Text = "Surround yourself with the dreamers and the doers, the believers and thinkers. But, most of all, surround yourself with those who see greatness within you, even when you don’t see it yourself.", Author = "Daniella Okeke" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Boo_Boo_Runs_Wild", Text = "Huh? Wha? 12 o'clock? It's too soon for noon!", Author = "Boo Boo Runs Wild" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Plesiosauria", Text = "A snake drawn through the shell of a turtle", Author = "Plesiosauria" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bience_Gawanas", Text = "It was like a dream, that in my lifetime we are going back to Namibia. My eldest daughter was born in a refugee camp,", Author = "Bience Gawanas" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wasi%27chu", Text = "My grandmother always referred to white people as the wasicu sica with emphasis on sica, our word for terrible or bad. ... Eventually I realized that it wasn't the white skin that I hated, but it was their culture of deceit, greed, racism and violence.", Author = "Wasi'chu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Prithvi_Narayan_Shah", Text = "If the citizens are wealthy, the country is strong. The King's storehouse is his people.", Author = "Prithvi Narayan Shah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Osterman_Weekend_%28film%29", Text = "The truth is just a lie that hasn't been found out.", Author = "The Osterman Weekend (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Parke_Godwin", Text = "Smart eats, stupid starves.", Author = "Parke Godwin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Despotism", Text = "The fundamental article of my political creed is, that despotism, or unlimited sovereignty, or absolute power, is the same in a majority of a popular assembly, an aristocratical council, an oligarchical junto, and a single emperor; equally arbitrary, cruel, bloody, and in every respect diabolical.", Author = "Despotism" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hunter_%281984_American_TV_series%29", Text = "Dee Dee McCall: [pursuing speeding car] C'mon, c'mon, you're losing him!\nRick Hunter: I'm already up to warp speed as it is, what do you want me to do?", Author = "Hunter (1984 American TV series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sulpicia", Text = "Tandem venit amor, qualem texisse pudori quam nudasse alicui sit mihi, Fama, magis.", Author = "Sulpicia" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Second_Apocalypse", Text = "Things holy ... became mere versions of things unholy ... as though the words holy and unholy were as easily exchanged as seats at a gaming table. And the recent simply became a more tawdry repetition of the ancient.", Author = "The Second Apocalypse" },
        new Quote { Id = "https://en.wikiquote.org/wiki/November_3", Text = "3 Kalki 16:11, 1 November 2005 (UTC) with a lean toward 4.", Author = "November 3" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mariam_Sankara", Text = "This is not a coup d'état. The military may have taken over, but that doesn't mean it's a coup d'état because the people have won. It's the people who fought this battle. The military are now there to ensure their safety.", Author = "Mariam Sankara" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anne_A._Amadi", Text = "I leave with mixed feelings on one hand with a sense of pride and satisfaction from the work we have been able to do together but again with an overwhelming sense of loss because through this council we have developed and cultivated deep personal connections with many of you.", Author = "Anne A. Amadi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nancy_Onyango", Text = "I know you hear a lot about financial empowerment of women in various hundreds of life right from the mama mbogas right up to people in school and", Author = "Nancy Onyango" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Revenge_of_the_Nerds", Text = "We've got bush! We've got bush!", Author = "Revenge of the Nerds" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Annalisa_Minetti", Text = "When you have faith, you can endure suffering. There are some sufferings that have no name, that you can't describe or justify, but when you believe in God, you no longer ask why me and not someone else. And that is a great achievement.", Author = "Annalisa Minetti" },
        new Quote { Id = "https://en.wikiquote.org/wiki/W._C._Fields", Text = "Here lies W. C. Fields. I would rather be living in Philadelphia.", Author = "W. C. Fields" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Open_Season_3", Text = "One day to guys' trip!", Author = "Open Season 3" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Catherine_Carswell", Text = "I have found that men, in all other ways admirable, have insisted upon flattery, upon extreme tact, upon suppression of opinion, in short, upon the sort of extreme and conscious consideration one shows to children or to persons suffering from nervous ailments.", Author = "Catherine Carswell" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Russell_T_Davies", Text = "Because it's the best idea ever invented in the history of the world!", Author = "Russell T Davies" },
        new Quote { Id = "https://en.wikiquote.org/wiki/West_of_Shanghai", Text = "Jane Creed: You've killed thousands of people.\nGen. Wu Yen Fang: Too many people in China. I kill only man - only bad man. When I kill bad man, I feel good. I have did good deed.\nJane Creed: And who decides whether a man is good or bad?\nGen. Wu Yen Fang: I do, I am Fang!", Author = "West of Shanghai" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Big_L", Text = "'Cause phony faggots I froze, it's a fact, I flip fast on foes with fabulous fantastic flows", Author = "Big L" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Death_Kiss", Text = "Say, will you go up to your office and write bad little boy five hundred times?", Author = "The Death Kiss" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jungle_Cruise_%28film%29", Text = "You booked a river cruise and you can't swim?", Author = "Jungle Cruise (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ann_Taylor_%28poet%29", Text = "Who ran to help me when I fell,And would some pretty story tell,Or kiss the place to make it well?My mother.", Author = "Ann Taylor (poet)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yuyi_Morales", Text = "Everything in my life is an art project...to me it is all art.", Author = "Yuyi Morales" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Langland", Text = "In a somer seson, whan softe was the sonne, I shoop me into shroudes as I a sheep were,In habite as an heremite unholy of werkes, Wente wide in this world wondres to here. Ac on a May morwenynge on Malverne hilles Me bifel a ferly, of Fairye me thoghte.", Author = "William Langland" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Denman%2C_1st_Baron_Denman", Text = "A delusion, a mockery, and a snare.", Author = "Thomas Denman, 1st Baron Denman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Aleksandr_Abdulov", Text = "If you don't know how to play, then play weird and you'll be known as a genius.", Author = "Aleksandr Abdulov" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fatiha_Boudiaf", Text = "I have the videotape of the Annaba tragedy.", Author = "Fatiha Boudiaf" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yama", Text = "I know the knowledge that leads to heaven. I will explain it to you so that you will understand it. O Nachiketas, remember this knowledge is the way to the endless world; the support of all worlds; and abides in subtle form within the intellects of the wise.", Author = "Yama" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jean-Michel_Jarre", Text = "I think that you have to seriously have fun, or taking serious things in a light way and obviously, for me, before all, music is made of fun and pleasure and excitement.", Author = "Jean-Michel Jarre" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rebel_Moon_%E2%80%93_Part_One%3A_A_Child_of_Fire", Text = "[Narrating] On the Motherworld, one thousand kings ruled unchallenged in succession. But in the royal bloodline's lust for power, they consumed everything upon their planet. The Realm marched its armies into the vastness of space, conquering everything in its path.", Author = "Rebel Moon – Part One: A Child of Fire" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Juliusz_Janusz", Text = "Good local and regional governance, is indeed the conditio sine qua non for local and regional authorities to faithfully keep to their mission of serving the common good of the communities.", Author = "Juliusz Janusz" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Christine_Nakimwero_Kaaya", Text = "There are also other environmental acts that were passed but lack regulations to enforce them.", Author = "Christine Nakimwero Kaaya" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adunni_Ade", Text = "Islam I was taught teaches me that we are judged on our intentions by Allah alone. What’s within, not what you see. Not looking for acceptance from anyone. I want people to live their life’s to its full potentials.", Author = "Adunni Ade" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chen_Chi-chung", Text = "The notion that humankind can conquer nature should be changed, as extreme weather phenomena would cause agricultural losses no matter how strong flood-prevention facilities are.", Author = "Chen Chi-chung" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jiang_Yanyong", Text = "I simply couldn't believe what I was seeing...All the doctors and nurses who saw yesterday's news were furious...Zhang Wenkang is ... abandoning even his most basic standards of integrity as a doctor.", Author = "Jiang Yanyong" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adele_James", Text = "Just FYI, this kind of behavior won’t be tolerated on my account. You will be blocked without hesitation!!! If you don’t like the casting don’t watch the show. Or do & engage in (expert) opinion different to yours. Either way, I’M GASSED and will continue to be!", Author = "Adele James" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Blonde_Electra", Text = "We had second-hand clothes, we lived nine years in the Ukraine without running water so no showers for nine years! It was really tough to be honest with you", Author = "Blonde Electra" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Toluwani_Obayan", Text = "Speed is not an advantage when you're moving in the wrong direction.", Author = "Toluwani Obayan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/June_18", Text = "2 Kalki 19:11, 17 June 2007 (UTC) Good quote, but I would prefer to use one of his more profound statements about life issues in general.", Author = "June 18" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Rosaly_Lopes", Text = "Just showing a woman, in Houston’s [Texas, United States] control centre, was a very great inspiration for me,", Author = "Rosaly Lopes" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Elizabeth_Cady_Stanton", Text = "While the man is born to do whatever he can, for the woman and the negro there is no such privilege.", Author = "Elizabeth Cady Stanton" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lai_Pei-yuan", Text = "If I was to safeguard Taiwan, I would have to plant trees.", Author = "Lai Pei-yuan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Randomness", Text = "How dare we speak of the laws of chance? Is not chance the antithesis of all law?", Author = "Randomness" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Wilhelm_Wundt", Text = "The results of ethnic psychology constitute... our chief source of information regarding the general psychology of the complex mental processes.", Author = "Wilhelm Wundt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Yvonne_Reungoat", Text = "Up to now I have tried to make my life a gift for him. What is most important is that my life belongs to the Lord. He has often led me to hear him, unexpectedly, and this time he has come to me and I could not say no to what the Lord was asking me.", Author = "Yvonne Reungoat" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Labyrinths", Text = "Today-for tomorrow, today becomes yesterday: How many million promises can ever fill a basket...", Author = "Labyrinths" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Strange_Case_of_Doctor_Rx", Text = "Swell night for a murder!", Author = "The Strange Case of Doctor Rx" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ama_Bame_Busia", Text = "May be in future, we will see one, but he has been the best so far", Author = "Ama Bame Busia" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edmund_of_Abingdon", Text = "Nou goth sonne under wode,— Me reweth, Marie, thi faire Rode. Nou goth sonne under tre,— Me reweth, Marie, thi sone and the.", Author = "Edmund of Abingdon" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Khajag_Barsamian", Text = "Our culture, architecture, music and everything else is based on Christ. Faith is part of the Armenian identity, so in case of a vacuum in reign or political leadership, the Church is the driving force.", Author = "Khajag Barsamian" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Guy-Paul_Noujaim", Text = "I think the addict has a bad opinion of himself and of others. When he sees that somebody loves him and appreciates him, he begins to love life. Then, slowly, he can go forward in life. This needs time.", Author = "Guy-Paul Noujaim" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dragon_Knights", Text = "Alchemist Kharl: You don't know me? All little boys should know their mother. Wait... I can word that better...", Author = "Dragon Knights" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Oliphant", Text = "Men of Harlech! On to glory,See your banner, famed in story,Waves these burning words before ye,Britain scorns to yield!", Author = "Thomas Oliphant" },
        new Quote { Id = "https://en.wikiquote.org/wiki/I_Spy_%282002_film%29", Text = "I'm going to need a couple of jars of jelly on the plane and two parachutes.", Author = "I Spy (2002 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Penny", Text = "I've got pennies for my thoughts; now I'm rich.", Author = "Penny" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Lives_of_Others", Text = "Sozialismus muss irgendwo anfangen", Author = "The Lives of Others" },
        new Quote { Id = "https://en.wikiquote.org/wiki/4D_Man", Text = "Look, he's not a magician. He's not invisible. He can't fly.", Author = "4D Man" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charles_Henry_Fowler", Text = "Religions which depend upon arguments are failures. A religion, to be aggressive, must be experimental; men must be something and do something by means of it, which would be otherwise impossible; then they become both rhetoric and logic — persuasion and proof.", Author = "Charles Henry Fowler" },
        new Quote { Id = "https://en.wikiquote.org/wiki/John_Florio", Text = "England is the paradise of women, the purgatory of men, and the hell of horses.", Author = "John Florio" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Ecco_the_Dolphin", Text = "Ecco, if we breathe air, why do we live beneath the waves? -one of Ecco's podmates", Author = "Ecco the Dolphin" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Danger_Man", Text = "Drake: Your husband was murdered in an apartment on the other side of Rome… There was evidence that he was sharing that apartment with a woman.\nStella: Now you just surprised me, John… I never knew Frank had that much initiative.", Author = "Danger Man" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Utah_Phillips", Text = "I'm here to change the world, and if I am not, I am probably wasting my time.", Author = "Utah Phillips" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Leon_Uris", Text = "A soldier has one item that cannot be neglected. His feet. They are his wheels, his mechanised warfare.", Author = "Leon Uris" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tommie_Shelby", Text = "Philosophy & Public Affairs, vol. 35, no. 2, pp. 126–160", Author = "Tommie Shelby" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Albert_Lutuli", Text = "I do not hate the white man; you see, his position of domination has placed him in a position of moral weakness.", Author = "Albert Lutuli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Moms_Mabley", Text = "They say you shouldn't say nothin' about the dead unless it's good. He's dead. Good!", Author = "Moms Mabley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Luis_Augusto_Castro_Quiroga", Text = "It's not a bad idea to insist on discussions in another country in order to avoid the issue of location and to find a way to establish that humanitarian exchange.", Author = "Luis Augusto Castro Quiroga" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Haja_Afsatu_Kabba", Text = "Let’s not destroy what will benefit the whole country to an individual.", Author = "Haja Afsatu Kabba" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Patrick_James_Dunn", Text = "One key fruit from meeting with curial officials is the opportunity simply to meet in person. It is always easier to write, if the occasion arises, to someone whom one has met personally.", Author = "Patrick James Dunn" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Brian_Eno", Text = "I, I wish you could swim Like the dolphins Like dolphins can swim Though nothing, nothing will keep us together We can beat them, forever and ever Oh, we can be heroes just for one day.", Author = "Brian Eno" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Amphibian", Text = "Poor Tom, that eats the swimming frog, the toad, the tadpole, the wall newt, and the water.", Author = "Amphibian" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Peery", Text = "The myth of Minnesota liberalism made the reality of rigid segregation in the city all the more unbearable, but since they knew very little of the fight for freedom raging through China, India, the East Indies, Indochina and the Philippines, they could only imagine a fight within the system.", Author = "Nelson Peery" },
        new Quote { Id = "https://en.wikiquote.org/wiki/2015", Text = "Bridge of Spies (film) (2015).", Author = "2015" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Laura_McLeod-Katjirua", Text = "Out of the applications received, only two applicants were successfully allotted farming units for resettlement purposes", Author = "Laura McLeod-Katjirua" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eucharia_Anunobi_Ekwu", Text = "I use everything God has given to me to talk to people.", Author = "Eucharia Anunobi Ekwu" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adin_Ballou", Text = "But now, instead of discussion and argument, brute force rises up to the rescue of discomfited error, and crushes truth and right into the dust. Might makes right, and hoary folly totters on in her mad career escorted by armies and navies.", Author = "Adin Ballou" },
        new Quote { Id = "https://en.wikiquote.org/wiki/20_Million_Miles_to_Earth", Text = "I've had nightmares in my time, but I've never dreamed of anything like this.", Author = "20 Million Miles to Earth" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Amy_Krouse_Rosenthal", Text = "For anyone trying to discern what to do with their life: pay attention to what you pay attention to. That's pretty much all the info you need.", Author = "Amy Krouse Rosenthal" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edmund_H._North", Text = "There has been no attempt made in this series to be inspirational. War has not been painted as a delightful or glorious experience, but simply and straightforwardly as the cold, grim, scientific business that it is.", Author = "Edmund H. North" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Dumi_Mkokstad", Text = "My dad is a pastor, and my mom is a pastor’s wife. Both my parents are quite musical.", Author = "Dumi Mkokstad" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Avni_Doshi", Text = "...Ambivalence in a mother is too dangerous for the culture to integrate...", Author = "Avni Doshi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Star_Kid", Text = "Check it out: I'm Shaquille O'Neal.", Author = "Star Kid" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tears_for_Fears", Text = "All around me are familiar faces,Worn out places, worn out faces.Bright and early for their daily races,Going nowhere, going nowhere.And their tears are filling up their glasses,No expression, no expression.Hide my head I want to drown my sorrow,No tomorrow, no tomorrow.", Author = "Tears for Fears" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Despicable_Me_2", Text = "Listen! I do not want a refund; I want the fairy princess... please! Please, I am begging you!", Author = "Despicable Me 2" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Phantom_Tollbooth", Text = "It seems to me that almost everything is a waste of time.", Author = "The Phantom Tollbooth" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chris_Brummer", Text = "The appeal of any agreement depends on its terms.", Author = "Chris Brummer" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stella_Ford_Mugabo", Text = "This year’s retreat will take more days than the previous retreats because issues at hand require more time to enable leaders to come up with concrete resolutions to drive the nation to the next level.", Author = "Stella Ford Mugabo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eamonn_McCann", Text = "A lesser man than you? Name one.", Author = "Eamonn McCann" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Strange_Brew", Text = "[to Pam in a beer tank that's being flooded with beer] My brother and I used to say that drownin' in beer was like heaven, eh? Now he's not here, and I've got two soakers... this isn't heaven. This sucks!", Author = "Strange Brew" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Clifford_Allen%2C_1st_Baron_Allen_of_Hurtwood", Text = "He believed that Christianity stood for the bettering of their fellow men, and the raising of their condition. Were not these the very tenets of Socialism?", Author = "Clifford Allen, 1st Baron Allen of Hurtwood" },
        new Quote { Id = "https://en.wikiquote.org/wiki/William_Beebe", Text = "To be a Naturalist is better than to be a King.", Author = "William Beebe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chris_Given-Wilson", Text = "That there was a tendency for strong and successful kings to be succeeded by weak and unsuccessful ones is one of the commonplaces of medieval English history: Edward I was followed by Edward II, Edward III by Richard II, Henry V by Henry VI, and so on.", Author = "Chris Given-Wilson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Muslim_Brotherhood", Text = "It is a complex subject: the Muslim Brotherhood comprises both a transnational network, with links in the UK, and national organisations in and outside the Islamic world. The movement is deliberately opaque, and habitually secretive.", Author = "Muslim Brotherhood" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nicky_Wire", Text = "There’s no problem mixing style with socialism - Fidel Castro was stylish!", Author = "Nicky Wire" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Chen_Ming-tong", Text = "I hope that the team on the other side (Mainland China) can cooperate with us to contribute to the peaceful development of relations across the (Taiwan) strait, safeguard cross-strait security, and develop ideas for co-existence and mutual prosperity.", Author = "Chen Ming-tong" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_Cook", Text = "I whose ambition leads me not only farther than any other man has been before me, but as far as I think it possible for man to go ...", Author = "James Cook" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lech_Kaczy%C5%84ski", Text = "Piss off, lout! (Spieprzaj, dziadu)", Author = "Lech Kaczyński" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sheets_of_sound", Text = "As he learned harmonically from Davis and Monk, and developed his mechanical skills, a new more confident Coltrane emerged. He has used long lines and multinoted figures within these lines, but in 1958 he started playing sections that might be termed 'sheets of sound'.", Author = "Sheets of sound" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mary_Colum", Text = "Both Joyce and Proust give the same impression, that they have penetrated into reaches of the inner life of men and presented them with far more actuality than has been done before.", Author = "Mary Colum" },
        new Quote { Id = "https://en.wikiquote.org/wiki/50/50_%282011_film%29", Text = "[to Katherine] I’m sorry, but, I’m going to have to call you on that. It’s bullshit. That’s what everyone has been saying. You’ll get better and It’ll be fine. I don’t know why everyone is so fucking scared to say it. You’re dying, dude...It makes it worse.", Author = "50/50 (2011 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fred_Dekker", Text = "My dream participation would be to make as much money as humanly possible for doing nothing whatsoever.", Author = "Fred Dekker" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bolaji_Olamide", Text = "Well, in my team we don’t play under any pressure. We play with peace of mind, and in unity knowing that we are leaving everything in the hands of God. That’s the believe of our coach and her teachings.", Author = "Bolaji Olamide" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eleuterio_Francesco_Fortino", Text = "Growth in communion justifies the joy in Christians to be able to elevate a sincere thanksgiving to God, the concreteness of permanent divisions.", Author = "Eleuterio Francesco Fortino" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jorge_Manrique", Text = "Nuestras vidas son los ríos Que van a dar en Ia mar, Que es el morir.", Author = "Jorge Manrique" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Anselm_Weber", Text = "The way has been prepared: the Navajos are well-disposed toward the Catholic missionaries and give founded hopes for an abundant harvest of souls.", Author = "Anselm Weber" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Xolile_Tshabalala", Text = "In my grandfather’s house and my great-grandmother’s house there is no such thing as an only child.", Author = "Xolile Tshabalala" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Talk", Text = "It would talk;Lord, how it talked!", Author = "Talk" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lucy_Chege", Text = "I'm no longer a Kenyan. It's not an easy thing .", Author = "Lucy Chege" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cosmas_Batubara", Text = "It's better that we consolidate cooperation with nationalist forces to fight for national unity on the basis of integralistic insights. We should realize that within those national interests there lay our Catholic interests.", Author = "Cosmas Batubara" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Get_Smart", Text = "Smart: So, you're Mr Big?", Author = "Get Smart" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Edward_P._King", Text = "Tell General Wainwright that I have decided to surrender Bataan. This decision is solely my own, no member of my staff nor of my command has helped me to arrive at this decision. In my opinion, if I do not surrender to the Japanese, Bataan will be known as the greatest slaughter in history.", Author = "Edward P. King" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Don_Paterson", Text = "In the end, the desolate age always turns instinctively to Classicism, which if nothing else legislates against certain kinds of disappointment.", Author = "Don Paterson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Ghost_Road", Text = "We are Craiglockhart's success stories. Look at us. We don't remember, we don't feel, we don't think - at least beyond the confines of what's needed to do the job.", Author = "The Ghost Road" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pauline_Nalova_Lyonga", Text = "English speaking, French speaking, they are one, these students are seeking to study. The children are young; they are the children of tomorrow. They should leave the children alone.", Author = "Pauline Nalova Lyonga" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tuck_Everlasting_%282002_film%29", Text = "For some, time passes slowly, an hour can seem an eternity. For others, there's never enough. For the Tucks, it didn't exist.", Author = "Tuck Everlasting (2002 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Human_nature", Text = "Knowledge of human nature is the beginning and end of political education.", Author = "Human nature" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mehr_Chand_Mahajan", Text = "Practically the whole of our Muslim military and police has either deserted or has not behaved in a proper manner. The help that you kindly promised has not arrived and we are surrounded on all sides.", Author = "Mehr Chand Mahajan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Massie", Text = "I think Trump is at fault here [...] I watched almost all of his speech. I felt like it was inevitable.", Author = "Thomas Massie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Junichi_Iijima", Text = "My interest was then shifted to algorithmic aspects of combinatorial optimization, in particular dynamic programming and branch and bound algorithms.", Author = "Junichi Iijima" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Coomi_Kapoor", Text = "Probably no Indian politician can match Mukherjee’s enviable record as a long-distance runner. He had a ringside view of Indian politics for some five decades, though in his four-part memoir, he hid more secrets than he revealed of his eventful life.", Author = "Coomi Kapoor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hannibal_Rising", Text = "[as he is carving an 'M' symbol into his victim's chest] M For Mischa!", Author = "Hannibal Rising" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Marie_Windsor", Text = "Sure I'm sad I've never made it to being a big superstar, but I feel absolutely no bitterness. I came out of a town with 250 people and what I've done is extraordinary.", Author = "Marie Windsor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Takuboku_Ishikawa", Text = "Like to a stoneThat rolls down a hill, I have come to this day.", Author = "Takuboku Ishikawa" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lil_Peep", Text = "Clothes off, baby, I got good white.", Author = "Lil Peep" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lilian_Afegbai", Text = "It’s passion for me. But sometimes, your passion might not give you money.", Author = "Lilian Afegbai" },
        new Quote { Id = "https://en.wikiquote.org/wiki/White_Men_Can%27t_Jump", Text = "You see Billy it's like this, you either smoke or you get smoked. And you got smoked.", Author = "White Men Can't Jump" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lizz_Njagah", Text = "Growing up in a family where we were always encouraged to pursue our dreams made it safe for me to express mine.", Author = "Lizz Njagah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Paradine_Case", Text = "She had patience. She could wait. This was, indeed, no ordinary woman.", Author = "The Paradine Case" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Intellectual_responsibility", Text = "The contemporary explosion of information—including misinformation—makes intellectual responsibility more needed than ever. But we also need a mean between a dogmatic self-assurance and a disabling fear of conviction. ...", Author = "Intellectual responsibility" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Allison_Robertson", Text = "I feel it is really different to be there at a show. It is such a great feeling and I hope that doesn’t die with the Internet as so many other things have. Go out, support those bands, have a beer, listen to some live music and don’t forget about it!", Author = "Allison Robertson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Abraham_Cowley", Text = "Nothing so soon the drooping spirits can raise As praises from the men, whom all men praise.", Author = "Abraham Cowley" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cold_Case", Text = "Season 1\nSeason 2\nSeason 3\nSeason 4\nSeason 5\nSeason 6\nSeason 7", Author = "Cold Case" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jesse_Jackson", Text = "I am somebody. I am a somebody. I am a child of God. I may not be educated but I am somebody. I may not have any money but I am somebody. I may not eat steak every day but I am somebody. I may not look the way you look but I am somebody.", Author = "Jesse Jackson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Planned_obsolescence", Text = "The application of planned obsolescence to thought itself has the same merit as its application to consumer goods; the new is not only shoddier than the old, it fuels an obsolete social system that staves off its replacement by manufacturing the illusion that it is perpetually new.", Author = "Planned obsolescence" },
        new Quote { Id = "https://en.wikiquote.org/wiki/A.C._Cuza", Text = "A nation is all the individuals of same blood, forming by their cohesion a natural related collective being with it s own organs and state which are social classes and the State and the same soul, which is nationality.", Author = "A.C. Cuza" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Super_8_%28film%29", Text = "I know bad things happen. Bad things happen. But you can still live. You can still live.", Author = "Super 8 (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Alex_Trebek", Text = "I'm curious about everything - even things that don't interest me.", Author = "Alex Trebek" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Karl_E._Weick", Text = "In any potential collectivity, members have different interests, capabilities, preferences, and so forth. They want to accomplish different things. However, to achieve some of these diverse ends, concerted, interdependent actions are required.", Author = "Karl E. Weick" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Final_Fantasy_XI", Text = "Everyone: I hate Tarutaru and so should you.", Author = "Final Fantasy XI" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nigella_Lawson", Text = "The trouble with modern cooking is that the mood it induces in the cook is one of skin-of-the-teeth efficiency, all briskness and little pleasure.", Author = "Nigella Lawson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Diana_Wynne_Jones", Text = "Things we are accustomed to regard as myth or fairy story are very much present in people’s lives. Nice people behave like wicked stepmothers. Every day.", Author = "Diana Wynne Jones" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Catriona_Ward", Text = "...When done right, horror is a transformative experience...", Author = "Catriona Ward" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Audrey_Gadzekpo", Text = "We find the political capture of the broadcast media space, in particular, and the increasing concentration of the media in a few hands as worrying for the country’s democracy, and there is the need to address this situation.", Author = "Audrey Gadzekpo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Don_Siegel", Text = "If you're going to be a whore, be a high-priced whore.", Author = "Don Siegel" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Eric_R%C3%BCcker_Eddison", Text = "The harvest of this world is to the resolute, and he that is infirm of purpose is ground betwixt the upper and the nether millstone.", Author = "Eric Rücker Eddison" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mike_Harris", Text = "His friends and family swear they knew that once Mike Harris found politics, it was just a matter of time until he made it to the top. If pundits marvel at how he defied the polls to tap into grassroots discontent, they also might note that he did not have to go far to hear those rumblings", Author = "Mike Harris" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stella_Ndabeni-Abrahams", Text = "There is the Trinity – God the Father, the Son and the Holy Spirit. But others think there is also God Stella.", Author = "Stella Ndabeni-Abrahams" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Y%C5%8Dsuke_Matsuoka", Text = "Japan would take action in a decisive form if she had the feeling that otherwise she would lose a chance which could only occur once in a thousand years.", Author = "Yōsuke Matsuoka" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Richard_M._Sherman", Text = "Just a spoonful of sugar helps the medicine go down.", Author = "Richard M. Sherman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Netumbo_Nandi-Ndaitwah", Text = "Women have taken up their place in the world. Let us continue to embrace equity and shape a world where every woman is empowered to use her capacity to it’s potential.", Author = "Netumbo Nandi-Ndaitwah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lapsed_Catholic", Text = "He was of the faith chiefly in the sense that the church he currently did not attend was Catholic.", Author = "Lapsed Catholic" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Henryk_Mieczys%C5%82aw_Jagodzi%C5%84ski", Text = "The death of our dear brother in Christ certainly saddens us. But it is also an encouragement for all of us to continue with humility and simplicity in faithful service to the Gospel, always being prepared for the Lord's call.", Author = "Henryk Mieczysław Jagodziński" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Benita_Sena_Okity-Duah", Text = "I want to assure you that he is nowhere near me and he is even scared of me and I am going to make sure he is kept in the bush because I even dealt with a more stronger candidate. This is a baby and I am going teach him how to do politics.", Author = "Benita Sena Okity-Duah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Cohen", Text = "My beloved wife Peaches was adored by myself and her two sons. I shall bring them up with their mother in their hearts every day. We shall love her forever.", Author = "Thomas Cohen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Kenneth_D._Mackenzie", Text = "The organizational design is the responsibility of the CEO, and the designer's role is to act as midwife to aid in the rebirth of the organization.", Author = "Kenneth D. Mackenzie" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Bees", Text = "Men, like bees, want room. When the hive is overflowing, the bees will swarm, and will be likely to take up their abode where they find the best prospect for honey. In matters of this sort, men are very much like bees.", Author = "Bees" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Akira_Kubo", Text = "All directors always try to do their best. The kind of movie on which they are working does not matter. Directors are limited by the size of the production budget and the amount of time that they have to shoot a film, but they always try to do their best within those constraints.", Author = "Akira Kubo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Last_words_in_Star_Wars_media", Text = "We're losing power. There seems to be a problem with the main reactor.", Author = "Last words in Star Wars media" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Javier_Aguirresarobe", Text = "I like films that make me take risks, by which I mean in some way your photographic personality leaves a mark on it. On big films some of this spirit is diluted a little, you have little or no idea what will happen to the film after the final edit.", Author = "Javier Aguirresarobe" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Cecil_B._DeMille", Text = "Motion pictures are the most important contribution to literature and art since the invention of fiction.", Author = "Cecil B. DeMille" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Hot_Spot", Text = "If you fall out of bed again the cockroaches are gonna start talkin.", Author = "The Hot Spot" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jack_Abbott_%28author%29", Text = "Even European philosophers have taken notice that most of what we take for knowledge is nothing but bias and prejudice.", Author = "Jack Abbott (author)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/David_Johnson_%28Iowa_politician%29", Text = "I want to be among those in the party who are willing to live up to Republican principles.", Author = "David Johnson (Iowa politician)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hermann_G%C3%B6ring", Text = "Ah, the Jews, the Jews, they'll be the death of me yet!", Author = "Hermann Göring" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Scorched_earth", Text = "On the other hand, the European authors of this article consider that they have a responsibility concerning the misdeeds of colonialism in Africa. Like Italy, Spain also resorted to a strategy of scorched earth in its colonies, including the use of poison gas.", Author = "Scorched earth" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Giuseppe_Garibaldi", Text = "I offer neither pay, nor quarters, nor provisions; I offer hunger, thirst, forced marches, battles and death. Let him who loves his country in his heart, and not with his lips only, follow me.", Author = "Giuseppe Garibaldi" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Karlheinz_Stockhausen", Text = "Tuning In (1981) BBC documentary on Stockhausen.", Author = "Karlheinz Stockhausen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vincent_Coulibaly", Text = "No injustice, no attack on peace, on life, on man's fundamental rights can remain indifferent in the Church's eyes.", Author = "Vincent Coulibaly" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Manipur", Text = "Polo can be traced to origins in Manipur state c. 3100 BC when it was played as Sagol Kangjei. Other claims are of it being of Persian origin, having been played as Pulu c. 525 BC.", Author = "Manipur" },
        new Quote { Id = "https://en.wikiquote.org/wiki/ALF_%28TV_series%29", Text = "Season 1\nSeason 2\nSeason 3\nSeason 4", Author = "ALF (TV series)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Catherine_Kasavuli", Text = "Don't pray for your enemies to die. I'm telling you, you might bury all your relatives.", Author = "Catherine Kasavuli" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Louis_Anthony_DeSimone", Text = "I chose the army because my father was an American soldier in France during World War I. I wasn't sorry to go in, I wanted to serve my country.", Author = "Louis Anthony DeSimone" },
        new Quote { Id = "https://en.wikiquote.org/wiki/August_Dvorak", Text = "I'm tired of trying to do something worthwhile for the human race, they simply don't want to change!", Author = "August Dvorak" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tales_of_the_Teenage_Mutant_Ninja_Turtles_%28TV_series%29_%28season_1%29", Text = "Bishop: You wanna know why I'm doing this, mutant? Hmm?\nLeonardo: Bishop.\nBishop: Because mutants are a threat to all of humanity. I'll find you and the others, and I will show the world.", Author = "Tales of the Teenage Mutant Ninja Turtles (TV series) (season 1)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Book_of_Jeremiah", Text = "Be not afraid of their faces: for I am with thee to deliver thee, saith the Lord. Then the Lord put forth his hand, and touched my mouth. And the Lord said unto me, Behold, I have put my words in thy mouth", Author = "Book of Jeremiah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fast_Times_at_Ridgemont_High", Text = "What are you people, on dope?!", Author = "Fast Times at Ridgemont High" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Barry_Purves", Text = "When you write a project your imagination just flows! You usually have some idea about budget and schedule but still try to write freely and honestly. Then when you get the budget and you do have to compromise, but this is part of the process.", Author = "Barry Purves" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Faerie_Queene", Text = "The general end therefore of all the book is to fashion a gentleman or noble person in virtuous and gentle discipline.", Author = "The Faerie Queene" },
        new Quote { Id = "https://en.wikiquote.org/wiki/C._V._Raman", Text = "There is no Heaven, no Swarga, no Hell, no rebirth, no reincarnation and no immortality. The only thing that is true is that a man is born, he lives and he dies. Therefore, he should live his life properly.", Author = "C. V. Raman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sicario_%282015_film%29", Text = "The word Sicario comes from the zealots of Jerusalem, killers who hunted the Romans who invaded their homeland. In Mexico, Sicario means hitman.", Author = "Sicario (2015 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Viktor_Frankl", Text = "It is true, Logotherapy, deals with the Logos; it deals with Meaning. Specifically I see Logotherapy in helping others to see meaning in life. But we cannot give meaning to the life of others. And if this is true of meaning per se, how much does it hold for Ultimate Meaning?", Author = "Viktor Frankl" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Stephen_Kim_Sou-hwan", Text = "The most fundamental principle of legislation is to defend human rights. If a law violates the most fundamental right, the right to life, it commits a serious error.", Author = "Stephen Kim Sou-hwan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fernando_de_Rojas", Text = "It is the enemy whom we do not suspect who is the most dangerous.", Author = "Fernando de Rojas" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Swing_Vote_%282008_film%29", Text = "America needs someone who's bigger than their speeches.", Author = "Swing Vote (2008 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Complacency", Text = "The individual finds himself already with a stock of ideas. He decides to content himself with them and to consider himself intellectually complete. As he feels the lack of nothing outside himself, he settles down definitely amid his mental furniture. Such is the mechanism of self-obliteration.", Author = "Complacency" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jared_Logan", Text = "The Etch a Sketch is the toy for drawing that makes drawing almost impossible. It simulates what drawing would be like if you had crippling arthritis.", Author = "Jared Logan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Adaeze_Yobo", Text = "Marriage Is Not By Force.", Author = "Adaeze Yobo" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jan_Theuninck", Text = "Het zijn zo van die zaken die onlosmakelijk in mijn geest verbonden zijn, met woorden maak ik een beeld en omgekeerd.", Author = "Jan Theuninck" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hansel_%26_Gretel%3A_Witch_Hunters", Text = "The curse of hunger for crawling things. I really hate that one.", Author = "Hansel & Gretel: Witch Hunters" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Franco_Marini", Text = "Renzi is like Grillo, he is the embodiment of political inconsistency serving third-party interests. (October 16 , 2012)", Author = "Franco Marini" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Antony_Selvanayagam", Text = "To be politically motivate and politically sensitive to what is happening around us is part of our responsibility as Church. We must educate people on this – this is an important area but since it is delicate area, we must be prudent in going about it.", Author = "Antony Selvanayagam" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Pop_art", Text = "The reason I'm painting this way is that I want to be a machine, and I feel that whatever I do and do machine-like is what I want to do.", Author = "Pop art" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Mad_%28magazine%29", Text = "What, Me Worry? (#24 – 07/1955)", Author = "Mad (magazine)" }
    };
}